INSERT INTO _n1_b11_guard_0126(ok) SELECT CASE WHEN NOT EXISTS (SELECT 1 FROM japanese_jlpt_daily_sessions s JOIN japanese_jlpt_study_plans p ON p.id=s.plan_id WHERE p.plan_code='N1_2027_JUL' AND s.study_date BETWEEN '2027-02-18' AND '2027-03-03' AND (s.status <> 'not_started' OR s.started_at IS NOT NULL OR s.completed_at IS NOT NULL)) THEN 1 ELSE 0 END;
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4121','2027-02-18','難','なん','어려움; 곤란; 재난; 결점','困難・災難・欠点などを表す語。また『難しい』の意を添える語。','多くの難を乗り越えて、ようやく計画を実現した。','많은 어려움을 극복하고 마침내 계획을 실현했다.'),
('n1-4122','2027-02-18','カルテ','かるて','진료기록; 의무기록; 차트','医師が患者の症状・診断・治療内容などを記録する診療記録。','医師はカルテを確認してから診察を始めた。','의사는 진료기록을 확인한 뒤 진찰을 시작했다.'),
('n1-4123','2027-02-18','カテゴリー','かてごりー','범주; 카테고리; 분류','共通する性質によってまとめた部類・範囲。','商品をカテゴリー別に整理して表示する。','상품을 카테고리별로 정리해 표시한다.'),
('n1-4124','2027-02-18','トーン','とーん','톤; 말투; 색조; 음조','音・声・色・文章などの調子や全体的な雰囲気。','もう少し柔らかいトーンで説明したほうがいい。','조금 더 부드러운 말투로 설명하는 편이 좋다.'),
('n1-4125','2027-02-18','ドリル','どりる','드릴; 반복 연습 문제','穴を開ける工具。また、技能を身につけるための反復練習。','壁に穴を開けるためにドリルを使った。','벽에 구멍을 뚫기 위해 드릴을 사용했다.'),
('n1-4126','2027-02-18','クレーン','くれーん','크레인; 기중기','重い物を吊り上げて移動させる機械。','建設現場で大型クレーンが資材を運んでいる。','건설 현장에서 대형 크레인이 자재를 옮기고 있다.'),
('n1-4127','2027-02-18','デッサン','でっさん','데생; 소묘','鉛筆・木炭などで形や明暗を捉えて描く素描。','美術学校で人物のデッサンを練習した。','미술학교에서 인물 데생을 연습했다.'),
('n1-4128','2027-02-18','毎','ごと','~마다; 각각; 매번','名詞に付いて、その一つ一つ・そのたびごと、という意味を表す。','一週間ごとに進捗を確認する。','1주일마다 진행 상황을 확인한다.'),
('n1-4129','2027-02-18','終わる','おわる','끝나다; 종료되다','続いていた物事・期間・行為などが最後まで進み、終了する。','会議が予定より早く終わったため、残りの時間で資料を整理した。','회의가 예정보다 일찍 끝나 남은 시간에 자료를 정리했다.'),
('n1-4130','2027-02-18','甘い','うまい','맛있다; 능숙하다','『うまい』の意味で使われる歴史的・特殊な表記。現代では『旨い・美味い』またはひらがなが一般的。','古い資料では、現在とは異なる漢字表記で『うまい』と読ませる例が見られる。','옛 자료에서는 현재와 다른 한자 표기로 ‘うまい’라고 읽게 하는 예가 보인다.'),
('n1-4131','2027-02-18','痒い','かゆい','가렵다','皮膚がむずむずして、掻きたい感じがする。','虫に刺された所が痒くても、強くかかない方がよい。','벌레에 물린 곳이 가려워도 세게 긁지 않는 편이 좋다.'),
('n1-4132','2027-02-18','飲み込む','のみこむ','삼키다; 이해하다; 말을 참다','口に入れた物をのどの奥へ送る。また、事情・意味を理解したり、言おうとした言葉を抑えたりする。','複雑な仕組みでも図で説明されると内容を飲み込みやすい。','복잡한 구조라도 그림으로 설명되면 내용을 이해하기 쉽다.'),
('n1-4133','2027-02-18','擦る','かする','살짝 스치다; 긁히듯 닿다; 일부를 떼다','物に軽く触れる、すれすれに通る。また、利益などから一部を取る。','ボールが壁をかすって外へ出た。','공이 벽을 살짝 스치고 밖으로 나갔다.'),
('n1-4134','2027-02-18','上がる','あがる','오르다; 올라가다; 상승하다; 향상되다','低い所から高い所へ移る。また、価格・数値・水準・地位などが高くなる。','原材料費が上がったため、会社は一部商品の価格を見直すことにした。','원재료비가 올라 회사는 일부 상품의 가격을 재검토하기로 했다.'),
('n1-4135','2027-02-18','継ぐ','つぐ','잇다; 계승하다; 이어받다','前の人の仕事・役割・伝統・地位などを受け取り、その後を続ける。','彼は前任者の方針を継ぎながら、組織改革にも着手した。','그는 전임자의 방침을 이어받으면서 조직 개혁에도 착수했다.'),
('n1-4136','2027-02-18','下がる','さがる','내려가다; 떨어지다; 낮아지다','位置・数値・価格・温度・評価などが低くなる。また、後ろへ退く。','需要が落ち着いたことで、原材料の価格は徐々に下がってきた。','수요가 안정되면서 원재료 가격은 서서히 내려가고 있다.'),
('n1-4137','2027-02-18','包む','くるむ','감싸다; 둘러싸다; 싸다','布・紙などを巻くようにして物の周囲を覆う。','壊れやすい部品を柔らかい布で包んでから箱に入れた。','깨지기 쉬운 부품을 부드러운 천으로 감싼 뒤 상자에 넣었다.'),
('n1-4138','2027-02-18','広まる','ひろまる','퍼지다; 널리 알려지다; 보급되다','物事・情報・習慣などが広い範囲に行き渡り、多くの人に知られるようになる。','在宅勤務が広まったことで、働く場所に対する考え方も変化した。','재택근무가 널리 보급되면서 일하는 장소에 대한 생각도 달라졌다.'),
('n1-4139','2027-02-18','誇る','ほこる','자랑하다; 자부하다; 자랑으로 여기다','自分や自分に関係する人・物の優れた点を、誇らしく思ったり示したりする。','この研究所は世界でも有数の設備と長い実績を誇っている。','이 연구소는 세계에서도 손꼽히는 설비와 오랜 실적을 자랑하고 있다.'),
('n1-4140','2027-02-18','整える','ととのえる','정돈하다; 갖추다; 가다듬다; 조정하다','乱れたものをきちんとした状態にする。また、必要な条件・準備をそろえたり、心身・呼吸などを安定させたりする。','発表の前に資料を確認し、呼吸を整えてから会議室に入った。','발표 전에 자료를 확인하고 호흡을 가다듬은 뒤 회의실에 들어갔다.'),
('n1-4141','2027-02-19','ネガ','ねが','네거티브 필름; 음화','写真で明暗・色が反転したネガフィルム、またはその画像。','昔の写真のネガをデジタル化した。','옛 사진의 네거티브 필름을 디지털화했다.'),
('n1-4142','2027-02-19','レクリエーション','れくりえーしょん','레크리에이션; 여가 활동','気分転換や心身の回復のために行う遊び・運動・活動。','研修の最後に簡単なレクリエーションを行った。','연수 마지막에 간단한 레크리에이션을 했다.'),
('n1-4143','2027-02-19','ミスプリント','みすぷりんと','오식; 인쇄 오류; 오타','印刷上の誤り。誤植。','資料にミスプリントがあったので修正した。','자료에 인쇄 오류가 있어서 수정했다.'),
('n1-4144','2027-02-19','ストロボ','すとろぼ','스트로보; 섬광등; 플래시','短時間に強い光を発する撮影用などの発光装置。','暗い会場だったのでストロボを使って撮影した。','어두운 행사장이어서 플래시를 사용해 촬영했다.'),
('n1-4145','2027-02-19','画','かく','획; 한 획','漢字などを書くとき、一度に書く線や点。','この漢字は全部で十二画ある。','이 한자는 모두 12획이다.'),
('n1-4146','2027-02-19','矢','や','화살','弓につがえ、弦の力で飛ばす先の尖った細長い道具。','的の中心に矢が刺さった。','과녁 한가운데에 화살이 꽂혔다.'),
('n1-4147','2027-02-19','丈','たけ','길이; 기장; 키','物や衣服の縦の長さ。また、人などの身長。','このズボンは少し丈が長い。','이 바지는 기장이 조금 길다.'),
('n1-4148','2027-02-19','背負う','しょう','짊어지다; 등에 메다; 부담을 떠안다','背中に物を載せて持つ。また、責任・負担などを引き受ける。','彼は家族の期待を背負って大会に出場した。','그는 가족의 기대를 짊어지고 대회에 출전했다.'),
('n1-4149','2027-02-19','曲がる','まがる','굽다; 휘다; 방향을 틀다','まっすぐなものが曲線になる。また、進む方向を変える。','次の角を右に曲がってください。','다음 모퉁이에서 오른쪽으로 도세요.'),
('n1-4150','2027-02-19','喋る','しゃべる','말하다; 수다 떨다; 떠들다','人と話す。特に、気軽に多く話す。','友達と三時間も喋っていた。','친구와 세 시간이나 수다를 떨었다.'),
('n1-4151','2027-02-19','解く','ほどく','풀다; 끄르다; 풀어헤치다','結び目・縛ったもの・もつれなどをゆるめて元の状態に戻す。','靴ひもの結び目を解いた。','신발끈의 매듭을 풀었다.'),
('n1-4152','2027-02-19','捲る','まくる','걷어 올리다; 젖히다; 마구 ~하다','袖などを巻き上げる。また、動詞の連用形に付き、その動作を激しく・続けて行うことを表す。','暑かったのでシャツの袖を捲った。','더워서 셔츠 소매를 걷어 올렸다.'),
('n1-4153','2027-02-19','織る','おる','짜다; 엮어 만들다','縦糸と横糸などを組み合わせて布を作る。','職人が昔ながらの方法で布を織っている。','장인이 전통 방식으로 천을 짜고 있다.'),
('n1-4154','2027-02-19','大人しい','おとなしい','얌전하다; 온순하다; 조용하다','性格・態度が穏やかで、騒いだり反抗したりしない。','この犬はとても大人しく、人にもよく慣れている。','이 개는 매우 얌전하고 사람에게도 잘 길들어 있다.'),
('n1-4155','2027-02-19','歪む','いがむ','비뚤어지다; 일그러지다; 왜곡되다','形・方向などが曲がって正しくなくなる。また、心・考えなどが素直でなくなる。','強い力が加わって金属の枠が歪んでしまった。','강한 힘이 가해져 금속 틀이 일그러졌다.'),
('n1-4156','2027-02-19','生やす','はやす','기르다; 자라게 하다','髪・ひげ・草木などを生えたまま伸ばす、または生えるようにする。','彼は最近、あごひげを生やしている。','그는 최근 턱수염을 기르고 있다.'),
('n1-4157','2027-02-19','切り','きり','끝; 한계; ~뿐; ~한 채','区切り・限度を表す語。また『〜きり』の形で、それだけ・その状態のままという意味を表す。','彼とは一度会ったきり、その後は連絡を取っていない。','그와는 한 번 만난 뒤로 이후에는 연락하지 않았다.'),
('n1-4158','2027-02-19','何と','なんと','무려; 어쩜; 얼마나','驚き・感嘆を表す。また、予想以上の数量・程度を強調する。','その店はなんと百年以上も続いている。','그 가게는 무려 100년 넘게 이어지고 있다.'),
('n1-4159','2027-02-19','如何にも','いかにも','정말로; 과연; 정말 ~답게','まったくそのとおりだと感じられるさま。また、非常にそれらしく見えるさま。','彼はいかにも専門家らしい落ち着いた話し方をする。','그는 정말 전문가다운 차분한 말투를 쓴다.'),
('n1-4160','2027-02-19','跨がる','またがる','걸쳐 있다; 걸치다; 양쪽에 걸쳐 뻗다; 올라타다','二つ以上の場所・区域などにまたいで広がる。また、脚を左右に開いて乗る。','この山脈は三つの県に跨がっている。','이 산맥은 세 현에 걸쳐 있다.');
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4161','2027-02-20','婿','むこ','사위; 신랑','娘の夫。また、結婚する男性を指すこともある。','娘夫婦と婿の両親が一緒に食事をした。','딸 부부와 사위의 부모님이 함께 식사했다.'),
('n1-4162','2027-02-20','壇','だん','단; 연단; 단상','周囲より一段高く作った場所。演説・儀式などに用いる台。','受賞者が壇に上がって挨拶した。','수상자가 단상에 올라 인사했다.'),
('n1-4163','2027-02-20','膳','ぜん','상; 작은 밥상; 한 상 차림','食器や料理を載せる小さな台。また、一人分の食事・料理。','旅館では夕食が一人分ずつ膳に載せて運ばれてきた。','료칸에서는 저녁 식사가 한 사람분씩 작은 상에 담겨 나왔다.'),
('n1-4164','2027-02-20','粥','かゆ','죽; 쌀죽','米などを多めの水で柔らかく煮た食べ物。','体調が悪かったので、朝は粥だけを食べた。','몸 상태가 좋지 않아 아침에는 죽만 먹었다.'),
('n1-4165','2027-02-20','裾','すそ','옷자락; 밑단; 산기슭','衣服の下端・下に垂れた部分。また、山の麓の広がった部分。','長いスカートの裾が床につかないように持ち上げた。','긴 치마 자락이 바닥에 닿지 않도록 들어 올렸다.'),
('n1-4166','2027-02-20','桐','きり','오동나무','大きな葉を持ち、軽く加工しやすい木材が家具などに使われる落葉樹。','この古い箪笥は桐で作られている。','이 오래된 장롱은 오동나무로 만들어졌다.'),
('n1-4167','2027-02-20','封','ふう','봉함; 봉인; 봉투를 닫음','手紙・容器などを閉じて、開かないようにすること。また、その閉じた部分。','書類を封筒に入れて封をした。','서류를 봉투에 넣고 봉했다.'),
('n1-4168','2027-02-20','吊るす','つるす','매달다; 걸어 두다','紐などを使い、物を高い所から下げた状態にする。','濡れた服をベランダに吊るして乾かした。','젖은 옷을 베란다에 매달아 말렸다.'),
('n1-4169','2027-02-20','辿り着く','たどりつく','간신히 도착하다; 마침내 다다르다','苦労しながら進み、ようやく目的地・結論などに到達する。','長い山道を歩いて、やっと頂上に辿り着いた。','긴 산길을 걸어 마침내 정상에 도착했다.'),
('n1-4170','2027-02-20','恋する','こいする','사랑하다; 연모하다','ある人に恋愛感情を抱く。','若い頃、同じ学校の人に恋した。','젊었을 때 같은 학교 사람을 사랑했다.'),
('n1-4171','2027-02-20','縮まる','ちぢまる','줄어들다; 짧아지다; 좁아지다','長さ・距離・規模などが小さくなる。','改善を重ねて作業時間が大きく縮まった。','개선을 거듭해 작업 시간이 크게 줄었다.'),
('n1-4172','2027-02-20','指差す','ゆびさす','손가락으로 가리키다','指を向けて対象を示す。','子どもが空の飛行機を指差した。','아이가 하늘의 비행기를 손가락으로 가리켰다.'),
('n1-4173','2027-02-20','老ける','ふける','늙다; 나이 들어 보이다','年を取る。また、実際の年齢より年上に見える。','髪型を変えたら少し老けて見えた。','머리 모양을 바꾸니 조금 나이 들어 보였다.'),
('n1-4174','2027-02-20','突っ張る','つっぱる','버티다; 뻗대다; 팽팽해지다','力を入れて支える。また、意地を張って自分の主張を曲げない。','彼は最後まで自分の意見を突っ張った。','그는 끝까지 자기 의견을 굽히지 않았다.'),
('n1-4175','2027-02-20','増し','まし','증가; 추가; 그나마 나음','量・程度が増えること。また、二つを比べて一方がまだよい・ましだという意味を表す。','何も説明しないよりは、短くても理由を伝えたほうがまだましだ。','아무 설명도 하지 않는 것보다는 짧더라도 이유를 전하는 편이 그나마 낫다.'),
('n1-4176','2027-02-20','盗み','ぬすみ','도둑질; 훔침','他人の物をこっそり盗むこと。','店の商品を盗む行為は犯罪だ。','가게 물건을 훔치는 행위는 범죄다.'),
('n1-4177','2027-02-20','産む','うむ','낳다; 출산하다; 산출하다','子や卵を体外に出す。また、比喩的に新しいものを生み出す。','その技術革新が新しい産業を産んだ。','그 기술 혁신이 새로운 산업을 낳았다.'),
('n1-4178','2027-02-20','傲る','おごる','교만해지다; 우쭐해지다','自分が優れていると思い、思い上がる。','成功しても傲らず、周囲への感謝を忘れない。','성공해도 교만해지지 않고 주변에 대한 감사를 잊지 않는다.'),
('n1-4179','2027-02-20','出合う','であう','우연히 만나다; 마주치다','偶然人や出来事に出会う。','旅先で昔の友人に偶然出合った。','여행지에서 옛 친구를 우연히 만났다.'),
('n1-4180','2027-02-20','蜜','みつ','꿀; 꽃꿀; 단 즙','花などから得られる甘い液。また、蜂が集めて作る蜂蜜。','花の蜜を求めて蜂が集まってきた。','꽃꿀을 찾아 벌들이 모여들었다.'),
('n1-4181','2027-02-21','藁','わら','짚; 볏짚','稲などの穀物から実を取った後に残る乾いた茎。','昔は藁を使って縄や草履を作った。','옛날에는 짚으로 새끼줄이나 짚신을 만들었다.'),
('n1-4182','2027-02-21','皺','しわ','주름; 구김살','皮膚・紙・布などにできる細い筋や折れ目。','シャツの皺をアイロンで伸ばした。','셔츠의 주름을 다리미로 폈다.'),
('n1-4183','2027-02-21','股','また','가랑이; 사타구니; 갈라진 부분','両脚が分かれる部分。また、物が二つに分かれる部分。','ズボンの股の部分が破れてしまった。','바지 가랑이 부분이 찢어졌다.'),
('n1-4184','2027-02-21','唾','つば','침; 타액','口の中で分泌される液体。唾液。','緊張で口が乾き、唾を飲み込んだ。','긴장해서 입이 말라 침을 삼켰다.'),
('n1-4185','2027-02-21','檻','おり','우리; 철창; 감금 공간','動物などを閉じ込めておく囲い。また、比喩的に自由を奪う場所。','動物園では猛獣が丈夫な檻の中にいた。','동물원에서는 맹수가 튼튼한 우리 안에 있었다.'),
('n1-4186','2027-02-21','腿','もも','넓적다리; 허벅지','脚の付け根から膝までの部分。太もも。','長く走った後で腿の筋肉が痛くなった。','오래 달린 뒤 허벅지 근육이 아파졌다.'),
('n1-4187','2027-02-21','一定','いちじょう','일정함; 정해져 있음','一定していること、定まっていることを表す古風な読み。','条件が一定なら、結果も比較しやすい。','조건이 일정하면 결과도 비교하기 쉽다.'),
('n1-4188','2027-02-21','夜中','やちゅう','밤새; 밤사이; 밤 동안','夜の間。夜通し。','台風のため夜中ずっと強い風が吹いていた。','태풍 때문에 밤새 강한 바람이 불었다.'),
('n1-4189','2027-02-21','畜生','ちくしょう','젠장; 짐승; 축생','本来は動物・仏教の畜生を指す語。口語では怒り・悔しさを表す強い悪態として使う。','『畜生、あと一歩だったのに』と彼は悔しそうにつぶやいた。','‘젠장, 한 걸음만 더 갔으면 됐는데’라고 그는 분한 듯 중얼거렸다.'),
('n1-4190','2027-02-21','短大','たんだい','단기대학; 일본의 단기대학','『短期大学』の略。通常二年程度で専門的な教育を行う高等教育機関。','高校卒業後、短大で保育について学び、資格を取得した。','고등학교 졸업 후 단기대학에서 보육을 배우고 자격을 취득했다.'),
('n1-4191','2027-02-21','セレモニー','せれもにー','의식; 행사; 세리머니','公式の儀式や式典。','開会セレモニーが午前十時に始まる。','개회식이 오전 10시에 시작된다.'),
('n1-4192','2027-02-21','襟','えり','옷깃; 칼라; 목둘레 부분','衣服の首まわりに付いている部分。','シャツの襟をきちんと整えた。','셔츠의 옷깃을 단정히 정리했다.'),
('n1-4193','2027-02-21','織','おり','직조; 짜임; 직물','糸を組み合わせて布を織ること。また、その織り方・織物。','この布は独特の織が美しい。','이 천은 독특한 짜임이 아름답다.'),
('n1-4194','2027-02-21','児','こ','아이; 새끼','子ども。また、動物の子。','迷子になった児を係員が保護した。','길을 잃은 아이를 직원이 보호했다.'),
('n1-4195','2027-02-21','濠','ごう','해자; 도랑','城などの周囲に掘った堀。','城の周囲には深い濠が残っている。','성 주변에는 깊은 해자가 남아 있다.'),
('n1-4196','2027-02-21','侍','さむらい','사무라이; 무사','日本の武士。','その映画は江戸時代の侍を描いている。','그 영화는 에도 시대의 사무라이를 그리고 있다.'),
('n1-4197','2027-02-21','雫','しずく','물방울; 방울','液体の小さな滴。','葉の先から雨の雫が落ちた。','잎 끝에서 빗방울이 떨어졌다.'),
('n1-4198','2027-02-21','嬢','じょう','아가씨; 젊은 여성; ~양','若い女性を指す語。また、女性を表す接尾語。','受付嬢が来客を案内した。','안내 데스크 여직원이 방문객을 안내했다.'),
('n1-4199','2027-02-21','刺','とげ','가시; 뾰족한 것; 가시 돋친 말','植物などの鋭く尖った部分。また、比喩的に人を傷つける言葉。','指に小さな刺が刺さった。','손가락에 작은 가시가 박혔다.'),
('n1-4200','2027-02-21','段々','だんだん','점점; 차츰; 서서히','時間の経過とともに、少しずつある状態へ変化していくさま。','新しい仕事にも段々慣れ、以前ほど緊張しなくなった。','새 일에도 점점 익숙해져 예전만큼 긴장하지 않게 되었다.');
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4201','2027-02-22','地方','じかた','지방; 지역; 해안 쪽','ある地域・地方。また、海上から見た陸地側・沿岸側を指すことがある。','この地方では冬になると雪が多い。','이 지방은 겨울이 되면 눈이 많이 온다.'),
('n1-4202','2027-02-22','空間','あきま','빈방; 비어 있는 공간','空いている部屋・場所。特に借り手のいない空室。','この建物にはまだ空間がいくつかある。','이 건물에는 아직 빈방이 몇 개 있다.'),
('n1-4203','2027-02-22','金庫','かねぐら','금고; 금전 보관 창고','金銭や貴重品を保管するための箱や蔵。','昔、この蔵は商家の金庫として使われていた。','옛날 이 창고는 상가의 금고로 사용되었다.'),
('n1-4204','2027-02-22','土産','どさん','토산물; 그 지방의 산물','その土地で産出・生産される物。土地の産物。','各地の土産を集めた展示会が開かれた。','각지의 토산물을 모은 전시회가 열렸다.'),
('n1-4205','2027-02-22','一人','いちにん','한 사람; 일인','一人の人。漢語的・文語的な読みで、日常では『ひとり』が一般的。','規則には『一人一票を原則とする』と明記されている。','규정에는 ‘한 사람 한 표를 원칙으로 한다’고 명시되어 있다.'),
('n1-4206','2027-02-22','二人','ににん','두 사람; 이인','二人の人。漢語的な読みで、通常の日常語では『ふたり』が一般的。','二人三脚という表現は、二人が協力して行動することの比喩にも使われる。','이인삼각이라는 표현은 두 사람이 협력해 행동하는 것의 비유로도 쓰인다.'),
('n1-4207','2027-02-22','木綿','きわた','목화솜; 면화','ワタの実から採れる綿。また、その綿を生じる植物を指す古い・限定的な読み。','昔は木綿を栽培し、糸にして織物を作っていた。','예전에는 목화를 재배해 실로 만들어 직물을 짰다.'),
('n1-4208','2027-02-22','地形','じぎょう','지반 다지기; 기초 공사; 건축 기초','建築を始める前に地面をならして固めること。また、その基礎工事・基礎構造。','建物を建てる前に、地形を十分に固める必要がある。','건물을 짓기 전에 지반을 충분히 다지는 기초 공사가 필요하다.'),
('n1-4209','2027-02-22','火傷','かしょう','화상; 데인 상처','火や熱などによって皮膚・組織が損傷すること。','熱湯で手に火傷を負った。','뜨거운 물에 손을 데어 화상을 입었다.'),
('n1-4210','2027-02-22','城下','じょうか','성 아래; 성 주변 지역','城の周辺・城下町の地域。','城下には古い町並みが残っている。','성 주변에는 오래된 거리 풍경이 남아 있다.'),
('n1-4211','2027-02-22','一日','いちじつ','하루; 어느 날; 초하루','一日間、またはある一日。文語的・改まった文脈では月の初日を指すこともある。','事態が深刻なため、一日の猶予も許されない。','사태가 심각하기 때문에 하루의 유예도 허용되지 않는다.'),
('n1-4212','2027-02-22','中指','ちゅうし','가운뎃손가락; 중지','手の五本の指の中央にある指。','中指に小さな傷ができた。','가운뎃손가락에 작은 상처가 생겼다.'),
('n1-4213','2027-02-22','捕鯨','ほげい','포경; 고래잡이','鯨を捕獲すること。','捕鯨の歴史について資料を調べた。','포경의 역사에 대해 자료를 조사했다.'),
('n1-4214','2027-02-22','仲人','ちゅうにん','중매인; 중개인','人と人との間に立って関係を取り持つ人。特に結婚の仲立ちをする人。','昔は仲人を通して結婚相手を紹介してもらうことも多かった。','예전에는 중매인을 통해 결혼 상대를 소개받는 경우도 많았다.'),
('n1-4215','2027-02-22','汽船','きせん','기선; 증기선','蒸気機関を動力として進む船。','汽船の発達によって海上輸送は大きく変化した。','증기선의 발달로 해상 운송은 크게 변화했다.'),
('n1-4216','2027-02-22','来る','きたる','다가오다; 도래하다; 오는','ある時・出来事などが近づいて来る。特に改まった表現で使う。','来る十月に新しい制度が始まる。','오는 10월에 새로운 제도가 시작된다.'),
('n1-4217','2027-02-22','面白い','おもしろい','재미있다; 흥미롭다','興味を引き、楽しいと感じさせる。また、通常と違って興味深い。','結果そのものより、なぜその結果になったのかを考える過程が面白い。','결과 자체보다 왜 그런 결과가 나왔는지 생각하는 과정이 흥미롭다.'),
('n1-4218','2027-02-22','落ちる','おちる','떨어지다; 낮아지다; 탈락하다','上から下へ移る。程度・数値が下がる。また、試験・選考などに不合格になる。','景気が悪化すると消費者の購買意欲も落ちる傾向がある。','경기가 악화되면 소비자의 구매 의욕도 떨어지는 경향이 있다.'),
('n1-4219','2027-02-22','直ぐ','すぐ','곧; 바로; 즉시','時間・距離をほとんど置かず、直ちに。通常はひらがなで書く。','異常を検知した場合は、直ぐに担当者へ連絡してください。','이상을 감지한 경우 즉시 담당자에게 연락해 주세요.'),
('n1-4220','2027-02-22','落とす','おとす','떨어뜨리다; 낮추다; 지우다; 빠뜨리다','上から下へ落ちるようにする。程度を下げる、汚れを除く、必要なものを抜かすなど多様な意味を持つ。','確認項目を一つでも落とすと、重大な不具合を見逃すおそれがある。','확인 항목을 하나라도 빠뜨리면 중대한 결함을 놓칠 우려가 있다.'),
('n1-4221','2027-02-23','易い','やすい','쉽다; ~하기 쉽다','行為が容易であること。また動詞の連用形に付き『〜しやすい』の意味を表す。','専門用語を減らすと、初めて読む人にも理解し易い文章になる。','전문용어를 줄이면 처음 읽는 사람도 이해하기 쉬운 문장이 된다.'),
('n1-4222','2027-02-23','可愛らしい','かわいらしい','사랑스럽다; 귀엽다','小ささ・姿・しぐさなどに愛らしさがあり、好感を持たせる。','店の入口には可愛らしい動物の置物が並んでいた。','가게 입구에는 사랑스러운 동물 장식물이 늘어서 있었다.'),
('n1-4223','2027-02-23','日の丸','ひのまる','일장기; 일본 국기','白地の中央に赤い円を描いた日本の国旗。','国際大会の会場には参加国の旗とともに日の丸も掲げられていた。','국제대회 행사장에는 참가국의 국기와 함께 일장기도 걸려 있었다.'),
('n1-4224','2027-02-23','準急','じゅんきゅう','준급행; 완행보다 빠르고 급행보다 정차역이 많은 열차','普通列車より停車駅が少なく、急行より多く停車する列車・列車種別。','この駅には急行は止まらないが、準急は停車する。','이 역에는 급행은 서지 않지만 준급행은 정차한다.'),
('n1-4225','2027-02-23','余所見','よそみ','곁눈질; 한눈팔기','見るべき所から目をそらし、別の方を見ること。','運転中に余所見をしてはいけない。','운전 중에 한눈을 팔아서는 안 된다.'),
('n1-4226','2027-02-23','目蓋','まぶた','눈꺼풀','目を閉じると眼球を覆う皮膚。','眠くて目蓋が重い。','졸려서 눈꺼풀이 무겁다.'),
('n1-4227','2027-02-23','朝寝坊','あさねぼう','늦잠; 늦잠꾸러기','朝遅くまで寝ること。また、そのような人。','休日なので久しぶりに朝寝坊した。','휴일이라 오랜만에 늦잠을 잤다.'),
('n1-4228','2027-02-23','素敵','すてき','멋지다; 훌륭하다; 근사하다','心を引かれるほど魅力的で、すばらしいさま。','古い建物を生かした素敵な図書館で、地域の人々にも親しまれている。','오래된 건물을 살린 멋진 도서관으로 지역 주민들에게도 사랑받고 있다.'),
('n1-4229','2027-02-23','この頃','このごろ','요즘; 최근; 근래','少し前から現在までの、比較的近い時期。','この頃は朝晩が涼しくなり、秋らしさを感じるようになった。','요즘은 아침저녁으로 선선해져 가을다운 느낌이 들기 시작했다.'),
('n1-4230','2027-02-23','この間','このあいだ','얼마 전; 요전; 지난번','現在からそれほど離れていない過去のある時。先日。','この間教えてもらった店に、週末に家族と行ってみた。','얼마 전에 알려 준 가게에 주말에 가족과 가 봤다.'),
('n1-4231','2027-02-23','合わせ','あわせ','맞춤; 결합; 맞대기','二つ以上のものを合わせること。また、その組み合わせ。','部品の合わせが悪いと、隙間ができる。','부품의 맞춤이 좋지 않으면 틈이 생긴다.'),
('n1-4232','2027-02-23','片付け','かたづけ','정리; 치우기; 마무리','散らかった物を整理すること。また、仕事などを処理して終わらせること。','食事が終わったら、みんなで片付けをしよう。','식사가 끝나면 다 같이 정리하자.'),
('n1-4233','2027-02-23','何れ','いずれ','어느 것이든; 언젠가; 결국','複数の中のどれかを指す。また、将来のある時点・結局という意味でも使う。','何れの案を採用するにしても、追加の検証は必要だ。','어느 안을 채택하더라도 추가 검증은 필요하다.'),
('n1-4234','2027-02-23','答え','こたえ','답; 대답; 해답','質問・問題などに対して示す返事・解答。','正しい答えだけでなく、そこに至る考え方も説明してください。','정답뿐 아니라 거기에 이르는 사고 과정도 설명해 주세요.'),
('n1-4235','2027-02-23','取っ手','とって','손잡이','容器・扉・道具などを手で持ったり開閉したりするための部分。','古い扉の取っ手が外れかけていたので、新しいものに交換した。','낡은 문의 손잡이가 떨어질 듯해 새것으로 교체했다.'),
('n1-4236','2027-02-23','釣り','つり','낚시; 거스름돈','魚を釣ること。また『お釣り』の形で、支払額と代金との差額として返される金銭を指す。','休日には川で釣りをして過ごすことが多い。','휴일에는 강에서 낚시를 하며 보내는 경우가 많다.'),
('n1-4237','2027-02-23','控室','ひかえしつ','대기실; 대기실 방','出番・面会などを待つための部屋。','出演者は控室で本番を待っている。','출연자는 대기실에서 본방을 기다리고 있다.'),
('n1-4238','2027-02-23','昼間','ちゅうかん','낮; 주간','日が出て明るい時間帯。『ひるま』とも読む。','この道路は昼間は混雑するが、深夜になると交通量が大きく減る。','이 도로는 낮에는 혼잡하지만 심야가 되면 교통량이 크게 줄어든다.'),
('n1-4239','2027-02-23','肉体','にくたい','육체; 몸','精神に対して、人間や動物の身体そのものをいう語。','長時間の作業を続けるには、精神力だけでなく肉体的な負担にも配慮が必要だ。','장시간 작업을 계속하려면 정신력뿐 아니라 육체적 부담에도 배려가 필요하다.'),
('n1-4240','2027-02-23','教科','きょうか','교과; 과목','学校教育で、学習内容を一定の分野ごとにまとめた科目。','必修教科だけでなく、自分の関心に応じて選択科目も履修できる。','필수 교과뿐 아니라 자신의 관심에 따라 선택 과목도 수강할 수 있다.');
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4241','2027-02-24','秘書','ひしょ','비서','役員・政治家などを補佐し、文書・連絡・日程管理などの事務を担当する人。','社長の秘書が会議の日程を調整し、参加者に案内を送った。','사장의 비서가 회의 일정을 조정하고 참가자에게 안내를 보냈다.'),
('n1-4242','2027-02-24','原子','げんし','원자','元素の性質を保つ最小の粒子で、原子核と電子から構成されるもの。','物質は非常に小さな原子や分子によって構成されている。','물질은 매우 작은 원자와 분자로 구성되어 있다.'),
('n1-4243','2027-02-24','各種','かくしゅ','각종; 여러 종류','さまざまな種類。それぞれの種類。','申請に必要な各種証明書は、オンラインでも取得できるようになった。','신청에 필요한 각종 증명서는 온라인으로도 발급받을 수 있게 되었다.'),
('n1-4244','2027-02-24','何も','なにも','아무것도; 아무것도 특별히','否定表現とともに、何一つ～ない、という意味を表す。','今日は何も予定がない。','오늘은 아무 일정도 없다.'),
('n1-4245','2027-02-24','先に','さきに','먼저; 앞서; 이전에','時間・順序で前に。ほかより早く。','私は先に会議室へ行って準備しておきます。','저는 먼저 회의실에 가서 준비해 두겠습니다.'),
('n1-4246','2027-02-24','演ずる','えんずる','연기하다; 연주하다; 역할을 하다','劇などで役を演じる。また、音楽などを演奏する。','彼は舞台で重要な役を演ずる。','그는 무대에서 중요한 역할을 연기한다.'),
('n1-4247','2027-02-24','その上','そのうえ','게다가; 그뿐만 아니라; 또한','すでに述べた事柄に、さらに別の事柄を付け加える語。','この部屋は広く、その上、駅にも近い。','이 방은 넓고 게다가 역에서도 가깝다.'),
('n1-4248','2027-02-24','重んずる','おもんずる','중시하다; 존중하다; 소중히 여기다','価値のあるものとして大切に扱う。尊重する。','この会社は社員の自主性を重んずる。','이 회사는 직원의 자율성을 중시한다.'),
('n1-4249','2027-02-24','近付く','ちかづく','다가가다; 가까워지다; 친해지다','人・物・時期などとの距離が近くなる。また、人と親しくなる。','締め切りが近付くにつれて、問い合わせが増えてきた。','마감이 다가올수록 문의가 늘기 시작했다.'),
('n1-4250','2027-02-24','何となく','なんとなく','왠지; 어쩐지; 특별한 이유 없이','はっきりした理由はないが、何かそう感じるさま。','何となく今日はいいことがありそうな気がする。','왠지 오늘은 좋은 일이 있을 것 같은 기분이 든다.'),
('n1-4251','2027-02-24','何とも','なんとも','뭐라고도; 정말; 아무렇지도','言葉ではうまく表せないほど。また、否定表現とともに『少しも・何も』の意を表す。','その景色は何とも言えないほど美しかった。','그 풍경은 뭐라고 말할 수 없을 정도로 아름다웠다.'),
('n1-4252','2027-02-24','お洒落','おしゃれ','멋내기; 세련됨; 멋쟁이','服装などに気を配って洗練されていること。また、そのような人。','彼女はいつもお洒落な服を着ている。','그녀는 언제나 세련된 옷을 입고 있다.'),
('n1-4253','2027-02-24','何気ない','なにげない','무심한; 아무렇지 않은; 별 뜻 없는','特別な意図・関心がないように見えるさま。','彼の何気ない一言に救われた。','그의 무심코 한 한마디에 위로받았다.'),
('n1-4254','2027-02-24','傷付く','きずつく','상처 입다; 다치다; 마음에 상처를 받다; 손상되다','体に傷を負う。また、心・名誉・物などが損なわれる。','何気ない一言で相手が深く傷付くこともある。','무심코 한 한마디로 상대가 깊이 상처받는 경우도 있다.'),
('n1-4255','2027-02-24','馬鹿らしい','ばからしい','바보같다; 어처구니없다; 시시하다','愚かで、まともに取り合う価値がないと感じられる。','そんな馬鹿らしい噂を信じる必要はない。','그런 어처구니없는 소문을 믿을 필요는 없다.'),
('n1-4256','2027-02-24','何だかんだ','なんだかんだ','이러니저러니; 이런저런 말을 하며; 결국 이것저것','あれこれ言うこと。また、結局いろいろありながらも、という意味で使う。','何だかんだ言って、結局みんな参加した。','이러니저러니 해도 결국 모두 참가했다.'),
('n1-4257','2027-02-24','割合に','わりあいに','비교적; 의외로','他と比べると比較的。思ったより。','この問題は割合に簡単だった。','이 문제는 비교적 쉬웠다.'),
('n1-4258','2027-02-24','済まない','すまない','미안하다; 면목없다','相手に悪いことをしたと感じ、申し訳なく思う。','急に予定を変えてしまって、本当に済まない。','갑자기 일정을 바꿔서 정말 미안하다.'),
('n1-4259','2027-02-24','汚れ','けがれ','더러움; 부정함; 오염','清浄・純粋でないこと。宗教的・精神的な不浄を指すこともある。','神事の前に身の汚れを清めるという考え方がある。','신사 의식 전에는 몸의 부정을 씻는다는 사고방식이 있다.'),
('n1-4260','2027-02-24','同い年','おないどし','동갑; 같은 나이','年齢が同じであること。また、その人。','彼とは同い年なので話が合う。','그와는 동갑이라 이야기가 잘 통한다.'),
('n1-4261','2027-02-25','当て','あて','기대; 의지할 곳; 목표·예상','頼りにするもの・期待するもの。また、見込みや目標。','補助金を当てにして計画を立てたが、採択される保証はない。','보조금을 기대하고 계획을 세웠지만 채택된다는 보장은 없다.'),
('n1-4262','2027-02-25','付き','つき','~이 딸림; 부착됨; 조건이 붙음','名詞の後について、それが付属している・伴っていることを表す。','この物件は家具付きなので、入居後すぐに生活を始められる。','이 집은 가구가 딸려 있어서 입주 후 바로 생활을 시작할 수 있다.'),
('n1-4263','2027-02-25','当たり','あたり','적중; 당첨; ~당; 접촉·반응','当たることや当たったもの。くじ・予想などの的中、数量の基準を示す『〜当たり』などにも用いる。','一人当たりの作業量を減らすため、担当者を二人増員した。','1인당 작업량을 줄이기 위해 담당자를 두 명 증원했다.'),
('n1-4264','2027-02-25','掛け','かけ','외상; 후불 거래','代金をその場で払わず、後日まとめて支払う取引。掛け売り。','この店では法人客に限り、月末締めの掛けで取引できる。','이 가게에서는 법인 고객에 한해 월말 마감 후불 거래가 가능하다.'),
('n1-4265','2027-02-25','借り','かり','빌림; 빚; 신세','金銭・物などを借りること、または返すべき負債。比喩的に、人から受けた恩や負い目も表す。','以前助けてもらった借りがあるので、今回は私が力になりたい。','전에 도움을 받아 신세를 진 것이 있으니 이번에는 내가 힘이 되고 싶다.'),
('n1-4266','2027-02-25','受け取り','うけとり','수령; 받음; 영수증','物・金銭・書類などを受け取ること。また、その受領を証明する書面を指すこともある。','荷物の受け取りには、本人確認書類が必要です。','짐을 수령하려면 본인 확인 서류가 필요합니다.'),
('n1-4267','2027-02-25','憧れ','あこがれ','동경; 선망','理想の人・物・生活などに心を引かれ、そうなりたいと強く願う気持ち。','海外で働くことは、学生の頃からの憧れだった。','해외에서 일하는 것은 학생 때부터의 동경이었다.'),
('n1-4268','2027-02-25','手当て','てあて','수당; 처치; 치료','給与とは別に支給される金銭。また、けが・病気への応急の処置。','会社から住宅手当てが支給されている。','회사에서 주택 수당이 지급되고 있다.'),
('n1-4269','2027-02-25','進み','すすみ','진행; 진척','物事が前へ進むこと。また、その進み具合。','作業の進みが予定より少し遅れている。','작업 진척이 예정보다 조금 늦다.'),
('n1-4270','2027-02-25','荷造り','にづくり','짐 싸기; 포장','運搬・旅行などのために荷物をまとめて包むこと。','引っ越し前日に夜遅くまで荷造りをした。','이사 전날 밤늦게까지 짐을 쌌다.'),
('n1-4271','2027-02-25','届け','とどけ','신고; 신고서; 통지','役所・組織などに一定の事実を知らせること。また、その書類。','住所が変わったので変更の届けを出した。','주소가 바뀌어서 변경 신고를 냈다.'),
('n1-4272','2027-02-25','招き','まねき','초대; 초청; 부름','人を招くこと。招待。','友人の招きで京都を訪れた。','친구의 초대로 교토를 방문했다.'),
('n1-4273','2027-02-25','詫び','わび','사과; 사죄','自分の過失などについて謝ること。また、その言葉。','迷惑をかけた相手に詫びを入れた。','폐를 끼친 상대에게 사과했다.'),
('n1-4274','2027-02-25','ご無沙汰','ごぶさた','오랫동안 연락하지 못함; 오래 찾아뵙지 못함','長い間、訪問・連絡・便りなどをしないでいること。','長い間ご無沙汰してしまい、申し訳ありません。','오랫동안 연락드리지 못해 죄송합니다.'),
('n1-4275','2027-02-25','売り出し','うりだし','판매 개시; 특매; 세일','商品を売り始めること。また、特別に値段を下げて大量に販売すること。','商店街では週末に大売り出しが行われる。','상점가에서는 주말에 대규모 할인 판매가 열린다.'),
('n1-4276','2027-02-25','顔付き','かおつき','얼굴 생김새; 표정; 얼굴빛','顔の形・特徴。また、顔に現れる表情や様子。','説明を聞くうちに、彼の顔付きが次第に真剣になった。','설명을 듣는 동안 그의 표정이 점차 진지해졌다.'),
('n1-4277','2027-02-25','夜更け','よふけ','깊은 밤; 늦은 밤','夜がかなり遅くなったころ。','夜更けまで隣の部屋から話し声が聞こえていた。','늦은 밤까지 옆방에서 이야기 소리가 들렸다.'),
('n1-4278','2027-02-25','片思い','かたおもい','짝사랑','自分だけが相手を恋しく思い、相手からは同じ気持ちを返されていないこと。','高校時代、同じクラスの人に三年間片思いしていた。','고등학교 시절 같은 반 사람을 3년 동안 짝사랑했다.'),
('n1-4279','2027-02-25','見晴らし','みはらし','전망; 조망; 멀리 내다보이는 경치','遠くまで広く見渡せること。また、その眺め。','山頂からの見晴らしは素晴らしかった。','산 정상에서 바라본 전망은 훌륭했다.'),
('n1-4280','2027-02-25','出入り口','でいりぐち','출입구; 출입문','建物・場所などに出入りするための口・通路。','非常時には出入り口の前に荷物を置かないでください。','비상시를 위해 출입구 앞에 짐을 두지 마세요.');
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4281','2027-02-26','勤め先','つとめさき','직장; 근무처','自分が勤めている会社・職場。勤務先。','住所だけでなく勤め先も変更になった。','주소뿐 아니라 근무처도 바뀌었다.'),
('n1-4282','2027-02-26','宙返り','ちゅうがえり','공중제비; 공중회전','空中で体を一回転させること。','選手は空中で見事な宙返りを決めた。','선수는 공중에서 멋지게 공중제비를 성공시켰다.'),
('n1-4283','2027-02-26','ひょっと','ひょっと','혹시; 어쩌면; 우연히','もしかすると。何かの拍子に偶然。','ひょっとすると、彼も参加するかもしれない。','어쩌면 그도 참가할지도 모른다.'),
('n1-4284','2027-02-26','どうにか','どうにか','어떻게든; 간신히; 그럭저럭','方法はともかく、何とかして目的を達成するさま。また、ぎりぎりのところで成り立つさま。','締め切り直前だったが、どうにか資料を完成させることができた。','마감 직전이었지만 어떻게든 자료를 완성할 수 있었다.'),
('n1-4285','2027-02-26','しょっちゅう','しょっちゅう','자주; 늘; 수시로','非常に頻繁に。いつもと言ってよいほど。','彼は仕事中もしょっちゅうスマートフォンを確認している。','그는 일하는 중에도 자주 스마트폰을 확인한다.'),
('n1-4286','2027-02-26','がっちり','がっちり','튼튼하게; 단단히; 야무지게; 체격이 다부지게','体格・構造などが丈夫でしっかりしているさま。また、物をしっかり組み合わせるさま。','彼は肩幅が広く、がっちりした体格をしている。','그는 어깨가 넓고 체격이 다부지다.'),
('n1-4287','2027-02-26','てっきり','てっきり','틀림없이 ~라고 생각하다; 영락없이','間違いなくそうだと思い込むさま。実際には予想と違った場合によく使う。','てっきり今日が締切だと思っていた。','나는 영락없이 오늘이 마감일인 줄 알았다.'),
('n1-4288','2027-02-26','がっしり','がっしり','튼튼하게; 건장하게; 다부지게','体格・構造などが丈夫で、しっかりしているさま。','彼はがっしりした体格をしている。','그는 다부진 체격을 하고 있다.'),
('n1-4289','2027-02-26','振り','ふり','척; 시늉; 태도; 모습','実際にはそうでないのに、そのように見せる態度・動作。また、様子・態度。','彼は知らない振りをして、その場を通り過ぎた。','그는 모르는 척하며 그 자리를 지나갔다.'),
('n1-4290','2027-02-26','夜更かし','よふかし','밤늦게까지 깨어 있음; 밤샘','夜遅くまで寝ずに起きていること。','夜更かしが続くと朝起きるのがつらい。','밤늦게까지 깨어 있는 날이 계속되면 아침에 일어나기 힘들다.'),
('n1-4291','2027-02-26','打ち消し','うちけし','부정; 부인; 취소','ある内容を否定すること。文法では否定表現を指す。','この文では打ち消しの表現が使われている。','이 문장에는 부정 표현이 사용되고 있다.'),
('n1-4292','2027-02-26','目付き','めつき','눈빛; 눈매; 눈의 표정','目に表れる表情や視線の様子。','彼は急に真剣な目付きになった。','그는 갑자기 진지한 눈빛이 되었다.'),
('n1-4293','2027-02-26','及び','および','및; 그리고','複数の事柄を並べて結ぶ語。『そして』『ならびに』の意。','申請には本人確認書類及び住所を確認できる書類が必要です。','신청에는 본인 확인 서류 및 주소를 확인할 수 있는 서류가 필요합니다。'),
('n1-4294','2027-02-26','起こす','おこす','일으키다; 발생시키다; 깨우다','眠っている人を目覚めさせたり、物事・現象・事件などを生じさせたりする。','小さな確認不足が重大な事故を起こす可能性もある。','작은 확인 부족이 중대한 사고를 일으킬 가능성도 있다.'),
('n1-4295','2027-02-26','当たり前','あたりまえ','당연함; 당연한; 보통의','特に不思議ではなく、当然であること。また、普通であること。','以前は当たり前だと思われていた働き方も、社会の変化とともに見直されている。','예전에는 당연하다고 여겨졌던 근무 방식도 사회 변화와 함께 재검토되고 있다.'),
('n1-4296','2027-02-26','錆び','さび','녹; 녹슨 상태','金属の表面に生じる酸化物。','古い自転車のチェーンに錆びが出ている。','오래된 자전거 체인에 녹이 슬어 있다.'),
('n1-4297','2027-02-26','教え','おしえ','가르침','教えること。また、教えられた内容や教訓。','祖父の教えを守り、どんなときも約束を破らないようにしている。','할아버지의 가르침을 지켜 어떤 때에도 약속을 어기지 않으려고 한다。'),
('n1-4298','2027-02-26','作り','つくり','만듦새; 구조; 꾸밈새','物の構造や出来上がり方、外見上の構成。','この鞄は作りが丈夫なので、長く使えそうだ。','이 가방은 만듦새가 튼튼해서 오래 사용할 수 있을 것 같다。'),
('n1-4299','2027-02-26','動き','うごき','움직임; 동향','人や物の動作、または状況・社会などの変化や動向。','市場の動きを慎重に見ながら、投資の時期を判断する必要がある。','시장의 움직임을 신중히 살피면서 투자 시기를 판단할 필요가 있다。'),
('n1-4300','2027-02-26','過ぎ','すぎ','지남; ~가 지난 때','ある時刻・時期を越えたこと、またはその直後。','会議が長引き、会社を出たのは九時過ぎだった。','회의가 길어져 회사를 나온 것은 아홉 시가 조금 지난 뒤였다。'),
('n1-4301','2027-02-27','持ち','もち','지속성; 오래감; 보유·담당','物が長く使える程度、または持つこと・受け持つこと。','この電池は持ちがよく、一度充電すれば二日ほど使える。','이 배터리는 오래가서 한 번 충전하면 이틀 정도 사용할 수 있다。'),
('n1-4302','2027-02-27','調べ','しらべ','조사; 조사함','物事を詳しく調査・確認すること。','詳しい調べによって、故障の原因が部品の劣化だと分かった。','자세한 조사를 통해 고장의 원인이 부품 노후화라는 것을 알게 되었다。'),
('n1-4303','2027-02-27','知り合い','しりあい','지인; 아는 사람','互いに名前や顔などを知っていて、ある程度の付き合いがある人。','知り合いの紹介で、以前から興味のあった会社の担当者と話す機会を得た。','지인의 소개로 예전부터 관심 있던 회사 담당자와 이야기할 기회를 얻었다.'),
('n1-4304','2027-02-27','年寄り','としより','노인; 나이 든 사람','年を取った人を指す一般的な語。文脈や言い方によっては失礼に聞こえることがある。','この地域では、一人暮らしの年寄りを近所で見守る取り組みが続けられている。','이 지역에서는 혼자 사는 노인을 이웃이 지켜보는 활동이 계속되고 있다.'),
('n1-4305','2027-02-27','仕上げ','しあげ','마무리; 마감; 마지막 손질','仕事や製作の最後の段階で、完成させるために行う作業や手入れ。','報告書は内容がほぼ完成したので、今日は表現と誤字の仕上げに集中する。','보고서는 내용이 거의 완성되어 오늘은 표현과 오타를 다듬는 마무리 작업에 집중한다.'),
('n1-4306','2027-02-27','話し合い','はなしあい','대화; 협의; 논의','問題や方針について、関係者が互いに意見を出して相談すること。','一方的に決めるのではなく、当事者同士の話し合いで解決策を探すべきだ。','일방적으로 결정하지 말고 당사자끼리의 대화를 통해 해결책을 찾아야 한다.'),
('n1-4307','2027-02-27','ドライ','どらい','건조한; 드라이한; 냉정하고 담백한','乾いていること。また、人間関係・考え方などが感情に流されず、割り切っているさま。','彼は仕事上の判断ではかなりドライで、個人的な感情を持ち込まない。','그는 업무상 판단에서는 꽤 냉정해서 개인적인 감정을 끌어들이지 않는다.'),
('n1-4308','2027-02-27','シック','しっく','세련된; 차분하고 멋진','派手ではなく、上品で洗練されているさま。','店内は黒を基調としたシックな雰囲気だった。','가게 안은 검은색을 중심으로 한 차분하고 세련된 분위기였다.'),
('n1-4309','2027-02-27','グレー','ぐれー','회색; 애매한 상태','灰色。また、白黒がはっきりせず判断が曖昧な状態。','規則上は完全に禁止ではないが、かなりグレーなケースだ。','규정상 완전히 금지는 아니지만 상당히 애매한 사례다.'),
('n1-4310','2027-02-27','レギュラー','れぎゅらー','정규; 주전; 레귤러','正式・通常のもの。また、スポーツなどの正規の出場選手。','彼は今季からチームのレギュラーに選ばれた。','그는 이번 시즌부터 팀의 주전으로 뽑혔다.'),
('n1-4311','2027-02-27','ユニーク','ゆにーく','독특함; 유니크함','他にはあまりなく、独特で個性的なさま。','彼はユニークな発想で新製品を考えた。','그는 독특한 발상으로 신제품을 구상했다.'),
('n1-4312','2027-02-27','ナンセンス','なんせんす','난센스; 터무니없음','意味がなく、常識に合わないこと。','根拠のない噂を信じるのはナンセンスだ。','근거 없는 소문을 믿는 것은 터무니없다.'),
('n1-4313','2027-02-27','タイムリー','たいむりー','시기적절한; 적시에 맞는','時機に合っていて、ちょうどよいさま。','今の状況に合ったタイムリーな話題だった。','지금 상황에 맞는 시기적절한 화제였다.'),
('n1-4314','2027-02-27','アップ','あっぷ','상승; 증가; 업로드·클로즈업 등의 ''업''','上昇・増加を表す語。また、アップロード・クローズアップ・ウォームアップなどの略としても使う。','原材料費の上昇に伴い、来月から一部商品の価格がアップする。','원재료비 상승에 따라 다음 달부터 일부 상품 가격이 오른다.'),
('n1-4315','2027-02-27','メディア','めでぃあ','미디어; 매체','情報・意見などを多くの人に伝える媒体・手段。新聞、テレビ、インターネットなど。','同じ出来事でも、メディアによって取り上げ方が異なることがある。','같은 사건도 미디어에 따라 다루는 방식이 다를 수 있다.'),
('n1-4316','2027-02-27','アルミ','あるみ','알루미늄','軽くて加工しやすく、耐食性にも優れた銀白色の金属『アルミニウム』の略。','この容器は軽量化のためアルミで作られている。','이 용기는 경량화를 위해 알루미늄으로 만들어졌다.'),
('n1-4317','2027-02-27','アクセル','あくせる','액셀러레이터; 가속 페달','自動車などで、踏むとエンジンの出力を上げて速度を増すための装置・ペダル。','急にアクセルを踏み込まず、ゆっくり発進してください。','갑자기 가속 페달을 밟지 말고 천천히 출발해 주세요.'),
('n1-4318','2027-02-27','アンコール','あんこーる','앙코르; 재공연 요청','公演の終了後、観客が拍手などで追加の演奏・上演を求めること。また、その追加公演。','大きな拍手に応え、歌手はアンコールでもう一曲歌った。','큰 박수에 응해 가수는 앙코르로 한 곡을 더 불렀다.'),
('n1-4319','2027-02-27','各','おのおの','각자; 각각','複数の人・物の一つ一つ。それぞれ。','参加者は各々の立場から改善案を述べた。','참가자들은 각자의 입장에서 개선안을 말했다.'),
('n1-4320','2027-02-27','雑','ざつ','거칠다; 조잡하다; 잡다하다','やり方が粗く丁寧でない。また、さまざまなものが入り交じっている。','急いで作ったため、資料のまとめ方が少し雑になった。','급하게 만들다 보니 자료 정리가 조금 조잡해졌다.');
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4321','2027-02-28','乙','おつ','을; 둘째 등급; 색다르고 멋스러움','甲に次ぐ第二のもの。また、少し変わっていて趣があるさま。','こういう昔風の店も乙なものだ。','이런 옛날식 가게도 꽤 운치가 있다.'),
('n1-4322','2027-02-28','巻','まき','권; 책의 권 또는 두루마리','書物を分けた単位。また、巻物・巻いたものを指す語。','この全集は全十巻で構成され、年代順に作品が収録されている。','이 전집은 전 10권으로 구성되어 작품이 연대순으로 수록돼 있다.'),
('n1-4323','2027-02-28','行','ぎょう','행; 글의 줄; 수행','文字が縦・横に並んだ一列。また、仏教で教えを実践する修行を指す。','回答は各項目につき三行以内で記入してください。','답변은 각 항목당 세 줄 이내로 기입해 주세요.'),
('n1-4324','2027-02-28','印','いん','인장; 도장; 표식','本人・団体の確認を示すために押す印章。また、しるし。','申請書の指定欄に印を押して提出してください。','신청서의 지정란에 도장을 찍어 제출해 주세요.'),
('n1-4325','2027-02-28','柱','はしら','기둥; 핵심 축','建物を支える縦の構造物。また比喩的に、計画・組織などを支える中心的要素。','新しい経営計画では、人材育成を三つの柱の一つに位置付けている。','새 경영 계획에서는 인재 육성을 세 가지 핵심 축 중 하나로 규정하고 있다.'),
('n1-4326','2027-02-28','誠','まこと','진심; 성의; 진실','偽りのない真実の心。まごころ。','誠を尽くして説明すれば、相手にもこちらの考えが伝わるだろう。','진심을 다해 설명하면 상대에게도 이쪽의 생각이 전해질 것이다.'),
('n1-4327','2027-02-28','獣','けだもの','짐승; 야수; 비유적으로 인간답지 못한 사람','人間以外の獣類。比喩的に、人間らしい思いやりを欠く者を強く非難していうこともある。','物語では人間の姿をした獣が森の奥に住んでいると語られる。','이야기에서는 인간의 모습을 한 짐승이 숲 깊숙한 곳에 산다고 전해진다.'),
('n1-4328','2027-02-28','インターナショナル','いんたーなしょなる','국제적인; 국제적','国際的であるさま。複数の国に関係すること。','インターナショナルな環境で働いている。','국제적인 환경에서 일하고 있다.'),
('n1-4329','2027-02-28','ロマンチック','ろまんちっく','낭만적; 로맨틱함','現実的な計算よりも、夢・情緒・恋愛的な雰囲気を重んじるさま。','夜景の見えるレストランでロマンチックな時間を過ごした。','야경이 보이는 레스토랑에서 로맨틱한 시간을 보냈다.'),
('n1-4330','2027-02-28','システム','しすてむ','시스템; 체계; 제도','複数の要素が一定の仕組みで結びついて機能する全体。特に情報処理の仕組みや制度をいう。','新しい勤怠システムの導入に伴い、申請手順も変更された。','새 근태 시스템 도입에 따라 신청 절차도 변경되었다.'),
('n1-4331','2027-02-28','コメント','こめんと','논평; 의견; 코멘트','ある事柄について短く述べる意見・説明。また、それを述べること。','会社は報道機関の取材に対し、現時点ではコメントを控えると回答した。','회사는 언론사의 취재에 대해 현시점에서는 논평을 삼가겠다고 답했다.'),
('n1-4332','2027-02-28','ビジネス','びじねす','사업; 비즈니스; 업무','利益を目的とする事業・商取引。また、仕事上の活動。','海外でビジネスを展開するには、現地の法制度を理解する必要がある。','해외에서 사업을 전개하려면 현지 법제도를 이해할 필요가 있다.'),
('n1-4333','2027-02-28','データ','でーた','데이터; 자료','調査・分析・判断の基礎となる数値や事実などの情報。コンピューターで処理される情報もいう。','感覚だけで判断せず、過去三年間のデータを基に原因を分析した。','감각만으로 판단하지 않고 지난 3년간의 데이터를 바탕으로 원인을 분석했다.'),
('n1-4334','2027-02-28','デザイン','でざいん','디자인; 설계; 도안','目的・機能・外観を考えて形や構成を設計すること。また、その図案・意匠。','見た目だけでなく操作性も考慮して画面をデザインした。','외관뿐 아니라 조작성도 고려해 화면을 디자인했다.'),
('n1-4335','2027-02-28','ファイル','ふぁいる','파일; 서류철','書類を整理してとじる物。また、コンピューター上で一まとまりとして保存されるデータ。','設定ファイルを変更する前に、必ずバックアップを取ってください。','설정 파일을 변경하기 전에 반드시 백업을 해 주세요.'),
('n1-4336','2027-02-28','ポイント','ぽいんと','핵심; 요점; 포인트','物事の重要な点・要点。また、得点やサービス上の点数なども表す。','交渉のポイントは、双方が受け入れられる条件をどこまで具体化できるかにある。','협상의 핵심은 양측이 받아들일 수 있는 조건을 어디까지 구체화할 수 있느냐에 있다.'),
('n1-4337','2027-02-28','ファン','ふぁん','팬; 애호가; 송풍기·환풍기의 팬','特定の人・作品・競技などを熱心に好む人。また、空気を送るための羽根車式の装置。','新製品の発表会には、長年のブランドファンが大勢集まった。','신제품 발표회에는 오랫동안 그 브랜드를 좋아해 온 팬들이 많이 모였다.'),
('n1-4338','2027-02-28','スピード','すぴーど','속도; 속력; 진행 속도','物が動く速さ。また、仕事・変化・処理などが進む速さ。','市場の変化のスピードが速いため、意思決定にも迅速さが求められる。','시장 변화 속도가 빠르기 때문에 의사결정에도 신속함이 요구된다.'),
('n1-4339','2027-02-28','サイズ','さいず','크기; 치수; 사이즈','物の大きさ・寸法。特に衣服や靴などの規格上の大きさ。','画面サイズに応じてレイアウトが自動的に変わるよう設計されている。','화면 크기에 따라 레이아웃이 자동으로 바뀌도록 설계되어 있다.'),
('n1-4340','2027-02-28','ホール','ほーる','홀; 대형 실내 공간; 구멍','多数の人を収容できる広い室内空間。また、英語 hole に由来して穴を表す場合もある。','講演会は駅前の多目的ホールで開催される。','강연회는 역 앞 다목적 홀에서 개최된다.'),
('n1-4341','2027-03-01','ベスト','べすと','최선; 최고; 베스트; 조끼','最も良いこと・最善。また、袖のない上着を表す。','限られた期間の中でベストな方法を選ぶには、優先順位を明確にする必要がある。','제한된 기간 안에서 최선의 방법을 고르려면 우선순위를 명확히 할 필요가 있다.'),
('n1-4342','2027-03-01','メーカー','めーかー','제조사; 제조업체; 메이커','製品を製造する会社・業者。','不具合が見つかったため、メーカーが対象製品を無償で交換すると発表した。','결함이 발견되어 제조사가 대상 제품을 무상 교환한다고 발표했다.'),
('n1-4343','2027-03-01','ベース','べーす','기초; 기반; 베이스; 저음부','物事の基礎・土台。また、音楽の低音部・低音楽器や、野球の塁を表す。','過去の実績をベースにして、来年度の予算案を作成した。','과거 실적을 바탕으로 내년도 예산안을 작성했다.'),
('n1-4344','2027-03-01','ガイド','がいど','가이드; 안내자; 안내서','場所・旅行などを案内する人。また、手順・情報を案内する資料。','初めて利用する人向けに、設定手順をまとめたガイドが公開されている。','처음 이용하는 사람을 위해 설정 절차를 정리한 가이드가 공개되어 있다.'),
('n1-4345','2027-03-01','ショック','しょっく','충격; 쇼크','予想外の出来事などによって受ける強い精神的・身体的な衝撃。','長年続いた事業の撤退が突然発表され、社員は大きなショックを受けた。','오랫동안 이어 온 사업의 철수가 갑자기 발표되어 사원들은 큰 충격을 받았다.'),
('n1-4346','2027-03-01','ルール','るーる','규칙; 룰','行動・競技・制度などで守るべき決まり。','運用ルールを曖昧なままにすると、担当者ごとに判断が変わってしまう。','운용 규칙을 애매하게 두면 담당자마다 판단이 달라지게 된다.'),
('n1-4347','2027-03-01','マーク','まーく','표시; 표식; 마크','目印・記号・印。また、競技で相手を警戒して守ることや、記録を出すことを表す場合もある。','重要な項目には赤いマークを付け、確認漏れを防ぐようにした。','중요한 항목에는 빨간 표시를 붙여 확인 누락을 방지하도록 했다.'),
('n1-4348','2027-03-01','シート','しーと','좌석; 시트; 얇은 판·천','乗り物などの座席。また、紙・布・樹脂などの薄く広い一枚物。','作業台が汚れないように、透明な保護シートを敷いた。','작업대가 더러워지지 않도록 투명한 보호 시트를 깔았다.'),
('n1-4349','2027-03-01','オープン','おーぷん','개장; 개점; 공개; 열린 상태','店・施設などを開業・開放すること。また、隠さず開かれている状態。','駅前に新しい商業施設が来月オープンする予定だ。','역 앞에 새로운 상업시설이 다음 달 문을 열 예정이다.'),
('n1-4350','2027-03-01','ソース','そーす','출처; 정보원; 소스','情報・資料などの出所・情報源。また、コンピューター分野ではプログラムの元となるソースコードを指すこともある。','その数字を資料に使う前に、情報のソースが信頼できるか確認した。','그 수치를 자료에 사용하기 전에 정보의 출처가 신뢰할 수 있는지 확인했다.'),
('n1-4351','2027-03-01','メッセージ','めっせーじ','메시지; 전달 내용; 전언','相手に伝える言葉・内容・意図。また、通信手段で送る短い文章。','エラーメッセージの内容を確認すると、接続先が間違っていることが分かった。','오류 메시지 내용을 확인하니 접속 대상이 잘못되어 있다는 것을 알 수 있었다.'),
('n1-4352','2027-03-01','コミュニケーション','こみゅにけーしょん','의사소통; 커뮤니케이션','言葉・文字・表情などを通して、情報・考え・感情を互いに伝え合うこと。','認識のずれを防ぐには、担当者同士の継続的なコミュニケーションが欠かせない。','인식 차이를 막으려면 담당자끼리 지속적으로 소통하는 것이 필수적이다.'),
('n1-4353','2027-03-01','カット','かっと','자르기; 삭제; 삭감; 컷','切ること・切り取ること。髪を切ること、映像の一場面、内容や費用などを削ることにも用いる。','予算を一律にカットするのではなく、不要な支出を個別に見直すべきだ。','예산을 일률적으로 삭감하기보다 불필요한 지출을 개별적으로 재검토해야 한다.'),
('n1-4354','2027-03-01','レンジ','れんじ','범위; 레인지; 조리기기','範囲・幅。また、加熱調理に用いるレンジ・電子レンジなどの調理器具。','この製品は幅広い価格レンジを用意し、利用者の予算に応じて選べるようにしている。','이 제품은 폭넓은 가격대를 마련해 이용자의 예산에 따라 선택할 수 있게 했다.'),
('n1-4355','2027-03-01','ダウン','だうん','다운; 정지; 쓰러짐; 저하','機能・状態・数値などが下がること、または停止すること。競技で倒れることなどにも用いる。','アクセスが急増した影響でサーバーが一時ダウンした。','접속이 급증한 영향으로 서버가 일시적으로 다운됐다.'),
('n1-4356','2027-03-01','コーナー','こーなー','코너; 구석; 전용 구역·프로그램 코너','曲がり角・隅。また、売り場・番組などで特定の内容を扱う一区画・一部分。','書店には資格試験の参考書を集めた専用コーナーが設けられている。','서점에는 자격시험 참고서를 모은 전용 코너가 마련되어 있다.'),
('n1-4357','2027-03-01','スペース','すぺーす','공간; 자리; 여백','物を置いたり活動したりするための空間・場所。また、文字間などの空白。','限られたスペースを有効に使うため、収納を壁際にまとめた。','한정된 공간을 효율적으로 사용하기 위해 수납공간을 벽 쪽에 모았다.'),
('n1-4358','2027-03-01','ストレス','すとれす','스트레스; 심리적·신체적 부담','外部からの刺激や負担によって生じる、心理的・身体的な緊張や圧迫感。','長時間の勤務が続くと、心身に大きなストレスがかかる。','장시간 근무가 계속되면 심신에 큰 스트레스가 쌓인다.'),
('n1-4359','2027-03-01','センス','せんす','감각; 센스; 판단력; 취향을 알아보는 능력','物事のよさ・違い・状況などを直感的に感じ取り、適切に判断する感覚・能力。','彼女は色の組み合わせのセンスがよく、資料のデザインも見やすい。','그녀는 색 조합 감각이 좋아 자료 디자인도 보기 편하다.'),
('n1-4360','2027-03-01','タイトル','たいとる','제목; 타이틀; 선수권·칭호','作品・文章などにつける題名。また、競技などで優勝者が持つ称号・地位。','内容が一目で伝わるように、記事のタイトルを短く分かりやすくした。','내용을 한눈에 알 수 있도록 기사의 제목을 짧고 알기 쉽게 만들었다.');
INSERT INTO _n1_b11_words_0126(source_key,study_date,word,reading,meaning_ko,meaning_ja,example_ja,example_ko) VALUES
('n1-4361','2027-03-02','トラブル','とらぶる','문제; 말썽; 분쟁; 고장','予期しない問題・故障・もめ事など、正常な進行を妨げる出来事。','システムにトラブルが発生したため、サービスを一時停止して原因を調査した。','시스템에 문제가 발생해 서비스를 일시 중단하고 원인을 조사했다.'),
('n1-4362','2027-03-02','ブーム','ぶーむ','붐; 열풍; 일시적 유행','ある物事が一時的に非常に人気を集め、社会的に広く流行すること。','健康志向の高まりを背景に、発酵食品のブームが続いている。','건강 지향이 높아지면서 발효식품 열풍이 계속되고 있다.'),
('n1-4363','2027-03-02','コントロール','こんとろーる','제어; 통제; 조절; 컨트롤','機械・状況・感情などを目的に合わせて調整し、望ましい状態に保つこと。','緊張している時ほど、自分の感情をコントロールすることが重要だ。','긴장하고 있을수록 자신의 감정을 조절하는 것이 중요하다.'),
('n1-4364','2027-03-02','グラフ','ぐらふ','그래프; 도표','数量・割合・変化などの関係を、線・棒・円などを用いて視覚的に表した図。','売上の推移をグラフにすると、季節ごとの変化が分かりやすい。','매출 추이를 그래프로 만들면 계절별 변화를 알아보기 쉽다.'),
('n1-4365','2027-03-02','オンライン','おんらいん','온라인; 인터넷에 연결된 상태','インターネットなどの通信回線に接続されている状態。また、インターネットを利用して行うこと。','会議はオンラインで行うため、会社に出社する必要はない。','회의는 온라인으로 진행되므로 회사에 출근할 필요가 없다.'),
('n1-4366','2027-03-02','タイミング','たいみんぐ','타이밍; 적절한 시기','何かを行うのに適した時機。また、動作などを合わせる時点。','話を切り出すタイミングを逃して、結局何も言えなかった。','말을 꺼낼 타이밍을 놓쳐 결국 아무 말도 하지 못했다.'),
('n1-4367','2027-03-02','キャッチ','きゃっち','잡기; 받아내기; 포착','飛んでくる物を受け取ること。また、情報などを捉えること。','外野手が難しい打球を見事にキャッチした。','외야수가 어려운 타구를 멋지게 잡아냈다.'),
('n1-4368','2027-03-02','シナリオ','しなりお','시나리오; 각본; 예상 전개','映画などの脚本。また、想定される出来事の展開や計画。','最悪のシナリオも想定して対策を準備した。','최악의 시나리오도 가정해 대책을 준비했다.'),
('n1-4369','2027-03-02','フォーム','ふぉーむ','폼; 자세; 형식','運動などでの身体の姿勢・型。また、形式・入力用の様式。','コーチに走るときのフォームを直してもらった。','코치에게 달릴 때의 자세를 교정받았다.'),
('n1-4370','2027-03-02','コンタクト','こんたくと','접촉; 연락; 콘택트렌즈','接触・連絡。また、コンタクトレンズの略。','担当者と直接コンタクトを取って確認した。','담당자와 직접 연락해 확인했다.'),
('n1-4371','2027-03-02','フロント','ふろんと','프런트; 접수대; 전면','ホテルなどの受付。また、物の前面。','ホテルのフロントでチェックインの手続きをした。','호텔 프런트에서 체크인 절차를 밟았다.'),
('n1-4372','2027-03-02','ゲスト','げすと','손님; 게스트; 초대 출연자','招かれた客。また、番組などに招待されて出演する人。','今日の番組には有名な俳優がゲストとして出演する。','오늘 프로그램에는 유명 배우가 게스트로 출연한다.'),
('n1-4373','2027-03-02','モニター','もにたー','모니터; 화면','コンピューターなどの映像を表示する画面・装置。','新しいモニターは文字が見やすい。','새 모니터는 글자가 보기 쉽다.'),
('n1-4374','2027-03-02','サイクル','さいくる','사이클; 주기; 순환','一定の変化を経て元の状態に戻るまでの一巡り。','この製品は開発サイクルが短い。','이 제품은 개발 주기가 짧다.'),
('n1-4375','2027-03-02','ポジション','ぽじしょん','포지션; 위치; 역할','位置・立場・役割。特にスポーツで選手が担当する位置や役割。','チーム内で自分のポジションを理解することが大切だ。','팀 안에서 자신의 역할을 이해하는 것이 중요하다.'),
('n1-4376','2027-03-02','ジャンル','じゃんる','장르; 분야','文学・芸術などの種類・分野。','私は幅広いジャンルの音楽を聴く。','나는 다양한 장르의 음악을 듣는다.'),
('n1-4377','2027-03-02','ラベル','らべる','라벨; 표지; 꼬리표','商品・容器などに付け、内容や名称などを示す札・表示。','瓶のラベルに原材料が書かれている。','병 라벨에 원재료가 적혀 있다.'),
('n1-4378','2027-03-02','セクション','せくしょん','섹션; 부분; 부문','全体を区切った一部分。また、組織の部門。','報告書を三つのセクションに分けた。','보고서를 세 개의 섹션으로 나눴다.'),
('n1-4379','2027-03-02','ベストセラー','べすとせらー','베스트셀러; 많이 팔린 상품','一定期間に非常によく売れた本・商品。','その小説は発売直後にベストセラーになった。','그 소설은 발매 직후 베스트셀러가 되었다.'),
('n1-4380','2027-03-02','パンク','ぱんく','펑크; 타이어가 터짐; 펑크 록','タイヤなどに穴が開いて空気が抜けること。また、音楽のパンクを指す。','高速道路で車のタイヤがパンクした。','고속도로에서 자동차 타이어가 펑크 났다.'),
('n1-4381','2027-03-03','インテリ','いんてり','지식인; 인텔리','知識・教養の高い人。知識人。','彼はインテリらしい落ち着いた話し方をする。','그는 지식인다운 차분한 말투를 쓴다.'),
('n1-4382','2027-03-03','コマーシャル','こまーしゃる','광고; 상업 광고; CM','テレビ・ラジオなどで流す商品・企業などの広告。','この商品のコマーシャルをテレビで見た。','이 상품 광고를 텔레비전에서 봤다.'),
('n1-4383','2027-03-03','コントラスト','こんとらすと','대조; 대비','二つのものの違いがはっきり際立つこと。','白と黒のコントラストが印象的なデザインだ。','흰색과 검은색의 대비가 인상적인 디자인이다.'),
('n1-4384','2027-03-03','ソロ','そろ','솔로; 독창; 독주','歌唱・演奏などを一人で行うこと。また、その部分。','彼女はコンサートで初めてソロを担当した。','그녀는 콘서트에서 처음으로 솔로를 맡았다.'),
('n1-4385','2027-03-03','マッサージ','まっさーじ','마사지; 안마','手などで体を揉んだりさすったりして、筋肉の緊張や疲れを和らげること。','肩が凝ったのでマッサージを受けた。','어깨가 뭉쳐서 마사지를 받았다.'),
('n1-4386','2027-03-03','スチーム','すちーむ','스팀; 증기','蒸気。また、蒸気を利用した暖房など。','スチームで衣服のしわを伸ばした。','스팀으로 옷의 주름을 폈다.'),
('n1-4387','2027-03-03','ダンプ','だんぷ','덤프; 덤프트럭; 버리기','荷台を傾けて荷物を降ろすダンプカー。また、データなどをまとめて出力すること。','工事現場に大型のダンプが入ってきた。','공사 현장에 대형 덤프트럭이 들어왔다.'),
('n1-4388','2027-03-03','タイマー','たいまー','타이머; 시간 설정 장치','設定した時間を計ったり、一定時間後に機器を作動・停止させたりする装置。','料理が焦げないようにタイマーを十分に設定した。','요리가 타지 않도록 타이머를 10분으로 설정했다.'),
('n1-4389','2027-03-03','パトカー','ぱとかー','순찰차; 경찰차','警察が巡回・出動などに使う車。','事故現場にパトカーが到着した。','사고 현장에 경찰차가 도착했다.'),
('n1-4390','2027-03-03','スプリング','すぷりんぐ','스프링; 용수철','弾力を利用するばね。英語の spring に由来する。','椅子の中のスプリングが壊れた。','의자 안의 스프링이 망가졌다.'),
('n1-4391','2027-03-03','源','みなもと','근원; 원천; 발원지','川などが始まる場所。また、物事が生じる根本・起源。','利用者から寄せられた意見は、サービス改善の重要な発想の源になっている。','이용자가 보내 온 의견은 서비스 개선의 중요한 발상의 원천이 되고 있다.'),
('n1-4392','2027-03-03','像','ぞう','상; 형상; 이미지','人・物の姿をかたどったもの。また、心に描かれる姿・イメージ。','新しい望遠鏡は、従来より鮮明な像を映し出すことができる。','새 망원경은 기존보다 선명한 상을 비출 수 있다.'),
('n1-4393','2027-03-03','実','じつ','실제; 진실; 사실','表面や名目に対する、実際の内容・真実。『実は』の形では、事実を打ち明ける時にも用いる。','形式を整えるだけでなく、実のある議論を重ねる必要がある。','형식만 갖출 것이 아니라 내실 있는 논의를 거듭할 필요가 있다.'),
('n1-4394','2027-03-03','版','はん','판; 판본; 버전','印刷に用いる版。また、内容・時期などが異なる出版物の版やバージョン。','制度改正に合わせて、来月マニュアルの改訂版を公開する。','제도 개정에 맞춰 다음 달 매뉴얼 개정판을 공개한다.'),
('n1-4395','2027-03-03','財','ざい','재산; 재물; 자산','金銭・土地・物品など、経済的な価値を持つ財産。','彼は若い頃に事業を興し、一代で大きな財を成した。','그는 젊었을 때 사업을 일으켜 한 세대 만에 큰 재산을 모았다.'),
('n1-4396','2027-03-03','通','つう','정통한 사람; 전문가; ~통(문서 등의 수량)','ある分野の事情に詳しい人。また、手紙・書類などを数える助数的な用法もある。','彼は相当な映画通で、古い作品にも非常に詳しい。','그는 상당한 영화통이라 오래된 작품에도 매우 밝다.'),
('n1-4397','2027-03-03','初','はつ','처음; 최초; 첫-','初めてであること。また、名詞の前について『初めての』『その年最初の』という意を表す。','新製品は発売初日から予想を上回る注文を集めた。','신제품은 발매 첫날부터 예상을 웃도는 주문을 모았다.'),
('n1-4398','2027-03-03','非','ひ','잘못; 그릇됨; 비-; ~이 아님','正しくないこと・誤り。また、名詞の前について『それではない』『反する』という意を表す。','会社は判断の非を認め、利用者に正式に謝罪した。','회사는 판단의 잘못을 인정하고 이용자에게 공식적으로 사과했다.'),
('n1-4399','2027-03-03','編','へん','편; 부; 편성된 부분','書物・作品などを内容ごとに分けたまとまり。また、編集したものを示す語。','この教材は基礎編と実践編に分かれており、段階的に学べる。','이 교재는 기초편과 실전편으로 나뉘어 단계적으로 학습할 수 있다.'),
('n1-4400','2027-03-03','器','うつわ','그릇; 기량; 도량','物を入れる容器。また比喩的に、役割を担うための能力・資質・度量を表す。','大きな組織を率いるには、判断力だけでなく人を受け止める器も求められる。','큰 조직을 이끌기 위해서는 판단력뿐 아니라 사람을 포용하는 도량도 요구된다.');
INSERT INTO japanese_words(word,reading,meaning_ko,meaning_ja,jlpt_level_id,ai_status,note) SELECT s.word,s.reading,s.meaning_ko,s.meaning_ja,(SELECT id FROM jlpt_levels WHERE code='N1'),'reviewed','JLPT N1 batch 2027-02-18..2027-03-03' FROM _n1_b11_words_0126 s WHERE NOT EXISTS (SELECT 1 FROM japanese_words w WHERE w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL);
INSERT INTO _n1_b11_map_0126(source_key,word_id) SELECT s.source_key,MIN(w.id) FROM _n1_b11_words_0126 s JOIN japanese_words w ON w.word=s.word AND w.reading=s.reading AND w.deleted_at IS NULL GROUP BY s.source_key;
