INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4128","prompt":"「毎」の読み方として最も適切なものを選びなさい。","options":["たんだい","じぎょう","とって","ごと"],"answer":"ごと","explanationKo":"「毎」는 「ごと」라고 읽는다. 뜻은 ~마다; 각각; 매번이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4129","prompt":"「終わる」の読み方として最も適切なものを選びなさい。","options":["つぐ","つっぱる","おわる","きたる"],"answer":"おわる","explanationKo":"「終わる」는 「おわる」라고 읽는다. 뜻은 끝나다; 종료되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4130","prompt":"「甘い」の読み方として最も適切なものを選びなさい。","options":["おのおの","うまい","なにげない","なんだかんだ"],"answer":"うまい","explanationKo":"「甘い」는 「うまい」라고 읽는다. 뜻은 맛있다; 능숙하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4121","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n多くの（　）を乗り越えて、ようやく計画を実現した。","options":["難","システム","マーク","グラフ"],"answer":"難","explanationKo":"문맥상 「難」가 가장 자연스럽다. 어려움; 곤란; 재난; 결점라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4122","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n医師は（　）を確認してから診察を始めた。","options":["パトカー","捕鯨","コントロール","カルテ"],"answer":"カルテ","explanationKo":"문맥상 「カルテ」가 가장 자연스럽다. 진료기록; 의무기록; 차트라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4123","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n商品を（　）別に整理して表示する。","options":["画","檻","カテゴリー","オープン"],"answer":"カテゴリー","explanationKo":"문맥상 「カテゴリー」가 가장 자연스럽다. 범주; 카테고리; 분류라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4124","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nもう少し柔らかい（　）で説明したほうがいい。","options":["取っ手","トーン","皺","土産"],"answer":"トーン","explanationKo":"문맥상 「トーン」가 가장 자연스럽다. 톤; 말투; 색조; 음조라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4125","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n壁に穴を開けるために（　）を使った。","options":["ドリル","合わせ","借り","錆び"],"answer":"ドリル","explanationKo":"문맥상 「ドリル」가 가장 자연스럽다. 드릴; 반복 연습 문제라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4126","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n建設現場で大型（　）が資材を運んでいる。","options":["振り","巻","ベース","クレーン"],"answer":"クレーン","explanationKo":"문맥상 「クレーン」가 가장 자연스럽다. 크레인; 기중기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4127","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n美術学校で人物の（　）を練習した。","options":["獣","シート","デッサン","過ぎ"],"answer":"デッサン","explanationKo":"문맥상 「デッサン」가 가장 자연스럽다. 데생; 소묘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4131","prompt":"「皮膚がむずむずして、掻きたい感じがする。」という意味に最も近い語を選びなさい。","options":["割合に","痒い","シック","馬鹿らしい"],"answer":"痒い","explanationKo":"「痒い」의 핵심 의미는 가렵다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4132","prompt":"「口に入れた物をのどの奥へ送る。また、事情・意味を理解したり、言おうとした言葉を抑えたりする。」という意味に最も近い語を選びなさい。","options":["飲み込む","捲る","曲がる","近付く"],"answer":"飲み込む","explanationKo":"「飲み込む」의 핵심 의미는 삼키다; 이해하다; 말을 참다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4133","prompt":"「物に軽く触れる、すれすれに通る。また、利益などから一部を取る。」という意味に最も近い語を選びなさい。","options":["出合う","上がる","指差す","擦る"],"answer":"擦る","explanationKo":"「擦る」의 핵심 의미는 살짝 스치다; 긁히듯 닿다; 일부를 떼다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4134","prompt":"「低い所から高い所へ移る。また、価格・数値・水準・地位などが高くなる。」という意味に最も近い語を選びなさい。","options":["老ける","織る","上がる","吊るす"],"answer":"上がる","explanationKo":"「上がる」의 핵심 의미는 오르다; 올라가다; 상승하다; 향상되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4135","prompt":"「前の人の仕事・役割・伝統・地位などを受け取り、その後を続ける。」という意味に最も近い語を選びなさい。","options":["包む","継ぐ","曲がる","近付く"],"answer":"継ぐ","explanationKo":"「継ぐ」의 핵심 의미는 잇다; 계승하다; 이어받다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','grammar',1,'〜かと思えば','{"pattern":"〜かと思えば","meaningKo":"〜인가 했더니","explanation":"〜かと思えば는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"晴れたかと思えば、急に激しい雨が降り始めた。","ko":"문맥에서 〜인가 했더니의 의미로 쓰였다."},{"ja":"改善したかと思えば、別の不具合が見つかった。","ko":"이 문장도 〜인가 했더니의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','grammar',2,'〜かと思うと','{"pattern":"〜かと思うと","meaningKo":"〜인가 싶더니 곧","explanation":"〜かと思うと는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"電車が着いたかと思うと、大勢の客が一斉に降りた。","ko":"문맥에서 〜인가 싶더니 곧의 의미로 쓰였다."},{"ja":"警報が鳴ったかと思うと、照明がすべて消えた。","ko":"이 문장도 〜인가 싶더니 곧의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n晴れた（　）、急に激しい雨が降り始めた。","options":["〜かと思えば","〜かねない","〜だに","〜にあらず"],"answer":"〜かと思えば","explanationKo":"문맥상 〜인가 했더니를 나타내는 「〜かと思えば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n電車が着いた（　）、大勢の客が一斉に降りた。","options":["〜かねる","〜てしかるべき","〜にほかならない","〜かと思うと"],"answer":"〜かと思うと","explanationKo":"문맥상 〜인가 싶더니 곧를 나타내는 「〜かと思うと」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、質問が相次いだ。","options":["〜てはかなわない","〜の至り","〜か〜ないかのうちに","〜ざるを得ない"],"answer":"〜か〜ないかのうちに","explanationKo":"문맥상 〜하자마자를 나타내는 「〜か〜ないかのうちに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-18','reading',1,'外来語を日本語の意味で捉える','{"passage":"外来語が日本語でどのように使われるか調べることには、原語との違いを含めて実際の文脈を理解できることという意義がある。しかし、音が似ているだけで原語の意味をそのまま当てはめることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、日本語の用例と共起表現を基準に意味を確認することが重要なのである。","questions":[{"prompt":"「外来語を日本語の意味で捉える」について筆者が最も重視していることは何か。","options":["日本語の用例と共起表現を基準に意味を確認すること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"日本語の用例と共起表現を基準に意味を確認すること","explanationKo":"본문에서는 日本語の用例と共起表現を基準に意味を確認すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["音が似ているだけで原語の意味をそのまま当てはめること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"音が似ているだけで原語の意味をそのまま当てはめること","explanationKo":"주의할 점은 音が似ているだけで原語の意味をそのまま当てはめること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["原語との違いを含めて実際の文脈を理解できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"原語との違いを含めて実際の文脈を理解できること","explanationKo":"外来語が日本語でどのように使われるか調べること에는 原語との違いを含めて実際の文脈を理解できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4148","prompt":"「背負う」の読み方として最も適切なものを選びなさい。","options":["しょう","おる","ととのえる","ほこる"],"answer":"しょう","explanationKo":"「背負う」는 「しょう」라고 읽는다. 뜻은 짊어지다; 등에 메다; 부담을 떠안다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4149","prompt":"「曲がる」の読み方として最も適切なものを選びなさい。","options":["さがる","おごる","のみこむ","まがる"],"answer":"まがる","explanationKo":"「曲がる」는 「まがる」라고 읽는다. 뜻은 굽다; 휘다; 방향을 틀다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4150","prompt":"「喋る」の読み方として最も適切なものを選びなさい。","options":["またがる","こいする","しゃべる","えんずる"],"answer":"しゃべる","explanationKo":"「喋る」는 「しゃべる」라고 읽는다. 뜻은 말하다; 수다 떨다; 떠들다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4141","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n昔の写真の（　）をデジタル化した。","options":["通","ネガ","コーナー","ジャンル"],"answer":"ネガ","explanationKo":"문맥상 「ネガ」가 가장 자연스럽다. 네거티브 필름; 음화라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4142","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n研修の最後に簡単な（　）を行った。","options":["レクリエーション","実","付き","マッサージ"],"answer":"レクリエーション","explanationKo":"문맥상 「レクリエーション」가 가장 자연스럽다. 레크리에이션; 여가 활동라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4143","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n資料に（　）があったので修正した。","options":["キャッチ","壇","襟","ミスプリント"],"answer":"ミスプリント","explanationKo":"문맥상 「ミスプリント」가 가장 자연스럽다. 오식; 인쇄 오류; 오타라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4144","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n暗い会場だったので（　）を使って撮影した。","options":["地形","肉体","ストロボ","腿"],"answer":"ストロボ","explanationKo":"문맥상 「ストロボ」가 가장 자연스럽다. 스트로보; 섬광등; 플래시라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4145","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの漢字は全部で十二（　）ある。","options":["調べ","画","釣り","届け"],"answer":"画","explanationKo":"문맥상 「画」가 가장 자연스럽다. 획; 한 획라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4146","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n的の中心に（　）が刺さった。","options":["矢","教え","誠","マーク"],"answer":"矢","explanationKo":"문맥상 「矢」가 가장 자연스럽다. 화살라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4147","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこのズボンは少し（　）が長い。","options":["ガイド","オンライン","スチーム","丈"],"answer":"丈","explanationKo":"문맥상 「丈」가 가장 자연스럽다. 길이; 기장; 키라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4151","prompt":"「結び目・縛ったもの・もつれなどをゆるめて元の状態に戻す。」という意味に最も近い語を選びなさい。","options":["落ちる","生やす","解く","縮まる"],"answer":"解く","explanationKo":"「解く」의 핵심 의미는 풀다; 끄르다; 풀어헤치다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4152","prompt":"「袖などを巻き上げる。また、動詞の連用形に付き、その動作を激しく・続けて行うことを表す。」という意味に最も近い語を選びなさい。","options":["広まる","捲る","曲がる","出合う"],"answer":"捲る","explanationKo":"「捲る」의 핵심 의미는 걷어 올리다; 젖히다; 마구 ~하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4153","prompt":"「縦糸と横糸などを組み合わせて布を作る。」という意味に最も近い語を選びなさい。","options":["織る","継ぐ","産む","終わる"],"answer":"織る","explanationKo":"「織る」의 핵심 의미는 짜다; 엮어 만들다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4154","prompt":"「性格・態度が穏やかで、騒いだり反抗したりしない。」という意味に最も近い語を選びなさい。","options":["段々","てっきり","痒い","大人しい"],"answer":"大人しい","explanationKo":"「大人しい」의 핵심 의미는 얌전하다; 온순하다; 조용하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4155","prompt":"「形・方向などが曲がって正しくなくなる。また、心・考えなどが素直でなくなる。」という意味に最も近い語を選びなさい。","options":["広まる","来る","歪む","起こす"],"answer":"歪む","explanationKo":"「歪む」의 핵심 의미는 비뚤어지다; 일그러지다; 왜곡되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','grammar',1,'〜か〜ないかのうちに','{"pattern":"〜か〜ないかのうちに","meaningKo":"〜하자마자","explanation":"〜か〜ないかのうちに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"席に着くか着かないかのうちに、会議が始まった。","ko":"문맥에서 〜하자마자의 의미로 쓰였다."},{"ja":"説明が終わるか終わらないかのうちに、質問が相次いだ。","ko":"이 문장도 〜하자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','grammar',2,'〜そびれる','{"pattern":"〜そびれる","meaningKo":"〜할 기회를 놓치다","explanation":"〜そびれる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"話しかける機会を逃し、確認しそびれるところだった。","ko":"문맥에서 〜할 기회를 놓치다의 의미로 쓰였다."},{"ja":"忙しさのあまり、申請書を出しそびれた。","ko":"이 문장도 〜할 기회를 놓치다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n（　）、会議が始まった。","options":["〜ざるを得ない","〜てはかなわない","〜の至り","〜か〜ないかのうちに"],"answer":"〜か〜ないかのうちに","explanationKo":"문맥상 〜하자마자를 나타내는 「〜か〜ないかのうちに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n話しかける機会を逃し、確認し（　）ところだった。","options":["〜てはばからない","〜の極み","〜そびれる","〜ずにはいられない"],"answer":"〜そびれる","explanationKo":"문맥상 〜할 기회를 놓치다를 나타내는 「〜そびれる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの感謝は言葉だけでは表し（　）。","options":["〜ばそれまでだ","〜きれない","〜ずとも","〜ではあるまいし"],"answer":"〜きれない","explanationKo":"문맥상 전부 〜할 수 없다를 나타내는 「〜きれない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-19','reading',1,'多義語を一対一で暗記しない','{"passage":"一つの語が持つ複数の意味を学ぶことには、未知の文章でも文脈に合う解釈を選びやすくなることという意義がある。しかし、代表的な訳語だけでは比喩や専門的用法を見落とすことには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、用法ごとの主語と目的語と場面をまとめて覚えることが重要なのである。","questions":[{"prompt":"「多義語を一対一で暗記しない」について筆者が最も重視していることは何か。","options":["用法ごとの主語と目的語と場面をまとめて覚えること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"用法ごとの主語と目的語と場面をまとめて覚えること","explanationKo":"본문에서는 用法ごとの主語と目的語と場面をまとめて覚えること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["代表的な訳語だけでは比喩や専門的用法を見落とすこと","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"代表的な訳語だけでは比喩や専門的用法を見落とすこと","explanationKo":"주의할 점은 代表的な訳語だけでは比喩や専門的用法を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["未知の文章でも文脈に合う解釈を選びやすくなること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"未知の文章でも文脈に合う解釈を選びやすくなること","explanationKo":"一つの語が持つ複数の意味を学ぶこと에는 未知の文章でも文脈に合う解釈を選びやすくなること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4168","prompt":"「吊るす」の読み方として最も適切なものを選びなさい。","options":["きずつく","つるす","なんと","まがる"],"answer":"つるす","explanationKo":"「吊るす」는 「つるす」라고 읽는다. 뜻은 매달다; 걸어 두다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4169","prompt":"「辿り着く」の読み方として最も適切なものを選びなさい。","options":["たどりつく","きたる","あがる","つっぱる"],"answer":"たどりつく","explanationKo":"「辿り着く」는 「たどりつく」라고 읽는다. 뜻은 간신히 도착하다; 마침내 다다르다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4170","prompt":"「恋する」の読み方として最も適切なものを選びなさい。","options":["おる","おとす","まがる","こいする"],"answer":"こいする","explanationKo":"「恋する」는 「こいする」라고 읽는다. 뜻은 사랑하다; 연모하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4161","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n娘夫婦と（　）の両親が一緒に食事をした。","options":["インテリ","器","婿","タイトル"],"answer":"婿","explanationKo":"문맥상 「婿」가 가장 자연스럽다. 사위; 신랑라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4162","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n受賞者が（　）に上がって挨拶した。","options":["トーン","壇","初","宙返り"],"answer":"壇","explanationKo":"문맥상 「壇」가 가장 자연스럽다. 단; 연단; 단상라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4163","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n旅館では夕食が一人分ずつ（　）に載せて運ばれてきた。","options":["膳","ダンプ","桐","侍"],"answer":"膳","explanationKo":"문맥상 「膳」가 가장 자연스럽다. 상; 작은 밥상; 한 상 차림라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4164","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n体調が悪かったので、朝は（　）だけを食べた。","options":["織","中指","各種","粥"],"answer":"粥","explanationKo":"문맥상 「粥」가 가장 자연스럽다. 죽; 쌀죽라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4165","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n長いスカートの（　）が床につかないように持ち上げた。","options":["顔付き","話し合い","裾","教科"],"answer":"裾","explanationKo":"문맥상 「裾」가 가장 자연스럽다. 옷자락; 밑단; 산기슭라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4166","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの古い箪笥は（　）で作られている。","options":["コミュニケーション","桐","知り合い","データ"],"answer":"桐","explanationKo":"문맥상 「桐」가 가장 자연스럽다. 오동나무라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4167","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n書類を（　）筒に入れて封をした。","options":["封","シート","フロント","源"],"answer":"封","explanationKo":"문맥상 「封」가 가장 자연스럽다. 봉함; 봉인; 봉투를 닫음라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4171","prompt":"「長さ・距離・規模などが小さくなる。」という意味に最も近い語を選びなさい。","options":["重んずる","跨がる","老ける","縮まる"],"answer":"縮まる","explanationKo":"「縮まる」의 핵심 의미는 줄어들다; 짧아지다; 좁아지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4172","prompt":"「指を向けて対象を示す。」という意味に最も近い語を選びなさい。","options":["背負う","近付く","指差す","捲る"],"answer":"指差す","explanationKo":"「指差す」의 핵심 의미는 손가락으로 가리키다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4173","prompt":"「年を取る。また、実際の年齢より年上に見える。」という意味に最も近い語を選びなさい。","options":["何と","老ける","恋する","終わる"],"answer":"老ける","explanationKo":"「老ける」의 핵심 의미는 늙다; 나이 들어 보이다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4174","prompt":"「力を入れて支える。また、意地を張って自分の主張を曲げない。」という意味に最も近い語を選びなさい。","options":["突っ張る","跨がる","老ける","解く"],"answer":"突っ張る","explanationKo":"「突っ張る」의 핵심 의미는 버티다; 뻗대다; 팽팽해지다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4175","prompt":"「量・程度が増えること。また、二つを比べて一方がまだよい・ましだという意味を表す。」という意味に最も近い語を選びなさい。","options":["勤め先","アンコール","メーカー","増し"],"answer":"増し","explanationKo":"「増し」의 핵심 의미는 증가; 추가; 그나마 나음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','grammar',1,'〜きれない','{"pattern":"〜きれない","meaningKo":"전부 〜할 수 없다","explanation":"〜きれない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"一日では読みきれないほどの資料が届いた。","ko":"문맥에서 전부 〜할 수 없다의 의미로 쓰였다."},{"ja":"この感謝は言葉だけでは表しきれない。","ko":"이 문장도 전부 〜할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','grammar',2,'〜かねない','{"pattern":"〜かねない","meaningKo":"〜할 우려가 있다","explanation":"〜かねない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"曖昧な説明は重大な誤解を招きかねない。","ko":"문맥에서 〜할 우려가 있다의 의미로 쓰였다."},{"ja":"確認を省けば、同じ事故が起こりかねない。","ko":"이 문장도 〜할 우려가 있다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n一日では読み（　）ほどの資料が届いた。","options":["〜ではあるまいし","〜ばそれまでだ","〜きれない","〜ずとも"],"answer":"〜きれない","explanationKo":"문맥상 전부 〜할 수 없다를 나타내는 「〜きれない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n曖昧な説明は重大な誤解を招き（　）。","options":["〜まみれ","〜かねない","〜すら","〜とあれば"],"answer":"〜かねない","explanationKo":"문맥상 〜할 우려가 있다를 나타내는 「〜かねない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n個人情報のため、その質問には回答し（　）。","options":["〜かねる","〜だに","〜とみるや","〜めく"],"answer":"〜かねる","explanationKo":"문맥상 〜하기 어렵다를 나타내는 「〜かねる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-20','reading',1,'表記の揺れと標準形を区別する','{"passage":"同じ語の漢字表記と仮名表記を比較することには、古い資料や異なる媒体も読み取れるようになることという意義がある。しかし、見かける表記をすべて同じ頻度で使うと文章が不自然になることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、読解知識と自分が書く際の現代的な標準形を分けることが重要なのである。","questions":[{"prompt":"「表記の揺れと標準形を区別する」について筆者が最も重視していることは何か。","options":["読解知識と自分が書く際の現代的な標準形を分けること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"読解知識と自分が書く際の現代的な標準形を分けること","explanationKo":"본문에서는 読解知識と自分が書く際の現代的な標準形を分けること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["見かける表記をすべて同じ頻度で使うと文章が不自然になること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"見かける表記をすべて同じ頻度で使うと文章が不自然になること","explanationKo":"주의할 점은 見かける表記をすべて同じ頻度で使うと文章が不自然になること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["古い資料や異なる媒体も読み取れるようになること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"古い資料や異なる媒体も読み取れるようになること","explanationKo":"同じ語の漢字表記と仮名表記を比較すること에는 古い資料や異なる媒体も読み取れるようになること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4181","prompt":"「藁」の読み方として最も適切なものを選びなさい。","options":["にくたい","うりだし","わら","じぎょう"],"answer":"わら","explanationKo":"「藁」는 「わら」라고 읽는다. 뜻은 짚; 볏짚이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
