INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4184","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n緊張で口が乾き、（　）を飲み込んだ。","options":["オンライン","スチーム","切り","唾"],"answer":"唾","explanationKo":"문맥상 「唾」가 가장 자연스럽다. 침; 타액라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
