INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4191","prompt":"「公式の儀式や式典。」という意味に最も近い語を選びなさい。","options":["セレモニー","像","何れ","パンク"],"answer":"セレモニー","explanationKo":"「セレモニー」의 핵심 의미는 의식; 행사; 세리머니이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4192","prompt":"「衣服の首まわりに付いている部分。」という意味に最も近い語を選びなさい。","options":["コントロール","丈","短大","襟"],"answer":"襟","explanationKo":"「襟」의 핵심 의미는 옷깃; 칼라; 목둘레 부분이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4193","prompt":"「糸を組み合わせて布を織ること。また、その織り方・織物。」という意味に最も近い語を選びなさい。","options":["木綿","昼間","織","唾"],"answer":"織","explanationKo":"「織」의 핵심 의미는 직조; 짜임; 직물이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4194","prompt":"「子ども。また、動物の子。」という意味に最も近い語を選びなさい。","options":["動き","児","取っ手","進み"],"answer":"児","explanationKo":"「児」의 핵심 의미는 아이; 새끼이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4195","prompt":"「城などの周囲に掘った堀。」という意味に最も近い語を選びなさい。","options":["濠","錆び","柱","ルール"],"answer":"濠","explanationKo":"「濠」의 핵심 의미는 해자; 도랑이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','grammar',1,'〜かねる','{"pattern":"〜かねる","meaningKo":"〜하기 어렵다","explanation":"〜かねる는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"根拠のない提案には賛成しかねる。","ko":"문맥에서 〜하기 어렵다의 의미로 쓰였다."},{"ja":"個人情報のため、その質問には回答しかねます。","ko":"이 문장도 〜하기 어렵다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','grammar',2,'〜ざるを得ない','{"pattern":"〜ざるを得ない","meaningKo":"어쩔 수 없이 〜하다","explanation":"〜ざるを得ない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"安全が確認できず、運行を停止せざるを得ない。","ko":"문맥에서 어쩔 수 없이 〜하다의 의미로 쓰였다."},{"ja":"予算不足のため、計画を縮小せざるを得なかった。","ko":"이 문장도 어쩔 수 없이 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n根拠のない提案には賛成し（　）。","options":["〜めく","〜かねる","〜だに","〜とみるや"],"answer":"〜かねる","explanationKo":"문맥상 〜하기 어렵다를 나타내는 「〜かねる」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n安全が確認できず、運行を停止せ（　）。","options":["〜ざるを得ない","〜てしかるべき","〜ないまでも","〜をいいことに"],"answer":"〜ざるを得ない","explanationKo":"문맥상 어쩔 수 없이 〜하다를 나타내는 「〜ざるを得ない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n不公平な扱いを知り、疑問を抱か（　）。","options":["〜てはかなわない","〜にあらず","〜を禁じ得ない","〜ずにはいられない"],"answer":"〜ずにはいられない","explanationKo":"문맥상 〜하지 않고는 견딜 수 없다를 나타내는 「〜ずにはいられない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-21','reading',1,'検索語が結果を形づくる','{"passage":"情報を探すために検索語を選ぶことには、大量の資料から関連情報へ速く近づけることという意義がある。しかし、最初の用語に偏ると異なる立場や呼び方の資料が見えないことには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、同義語と上位概念と反対の立場の語でも検索することが重要なのである。","questions":[{"prompt":"「検索語が結果を形づくる」について筆者が最も重視していることは何か。","options":["同義語と上位概念と反対の立場の語でも検索すること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"同義語と上位概念と反対の立場の語でも検索すること","explanationKo":"본문에서는 同義語と上位概念と反対の立場の語でも検索すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["最初の用語に偏ると異なる立場や呼び方の資料が見えないこと","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"最初の用語に偏ると異なる立場や呼び方の資料が見えないこと","explanationKo":"주의할 점은 最初の用語に偏ると異なる立場や呼び方の資料が見えないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["大量の資料から関連情報へ速く近づけること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"大量の資料から関連情報へ速く近づけること","explanationKo":"情報を探すために検索語を選ぶこと에는 大量の資料から関連情報へ速く近づけること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4201","prompt":"「地方」の読み方として最も適切なものを選びなさい。","options":["ちゅうし","かくしゅ","みはらし","じかた"],"answer":"じかた","explanationKo":"「地方」는 「じかた」라고 읽는다. 뜻은 지방; 지역; 해안 쪽이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
