INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4204","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n各地の（　）を集めた展示会が開かれた。","options":["土産","フロント","源","朝寝坊"],"answer":"土産","explanationKo":"문맥상 「土産」가 가장 자연스럽다. 토산물; 그 지방의 산물라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
