INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4207","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n昔は（　）を栽培し、糸にして織物を作っていた。","options":["憧れ","木綿","空間","答え"],"answer":"木綿","explanationKo":"문맥상 「木綿」가 가장 자연스럽다. 목화솜; 면화라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
