INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4210","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）には古い町並みが残っている。","options":["ベストセラー","編","城下","センス"],"answer":"城下","explanationKo":"문맥상 「城下」가 가장 자연스럽다. 성 아래; 성 주변 지역라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
