INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4212","prompt":"「手の五本の指の中央にある指。」という意味に最も近い語を選びなさい。","options":["中指","マッサージ","粥","児"],"answer":"中指","explanationKo":"「中指」의 핵심 의미는 가운뎃손가락; 중지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4213","prompt":"「鯨を捕獲すること。」という意味に最も近い語を選びなさい。","options":["切り","短大","地形","捕鯨"],"answer":"捕鯨","explanationKo":"「捕鯨」의 핵심 의미는 포경; 고래잡이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4214","prompt":"「人と人との間に立って関係を取り持つ人。特に結婚の仲立ちをする人。」という意味に最も近い語を選びなさい。","options":["売り出し","仕上げ","仲人","肉体"],"answer":"仲人","explanationKo":"「仲人」의 핵심 의미는 중매인; 중개인이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4215","prompt":"「蒸気機関を動力として進む船。」という意味に最も近い語を選びなさい。","options":["メッセージ","汽船","調べ","ビジネス"],"answer":"汽船","explanationKo":"「汽船」의 핵심 의미는 기선; 증기선이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','grammar',1,'〜ずにはいられない','{"pattern":"〜ずにはいられない","meaningKo":"〜하지 않고는 견딜 수 없다","explanation":"〜ずにはいられない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"その映像を見ると、当時を思い出さずにはいられない。","ko":"문맥에서 〜하지 않고는 견딜 수 없다의 의미로 쓰였다."},{"ja":"不公平な扱いを知り、疑問を抱かずにはいられなかった。","ko":"이 문장도 〜하지 않고는 견딜 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','grammar',2,'〜ずとも','{"pattern":"〜ずとも","meaningKo":"〜하지 않아도","explanation":"〜ずとも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"詳しく説明せずとも、図を見れば仕組みが分かる。","ko":"문맥에서 〜하지 않아도의 의미로 쓰였다."},{"ja":"名を挙げずとも、誰のことか明らかだった。","ko":"이 문장도 〜하지 않아도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその映像を見ると、当時を思い出さ（　）。","options":["〜ずにはいられない","〜てはかなわない","〜にあらず","〜を禁じ得ない"],"answer":"〜ずにはいられない","explanationKo":"문맥상 〜하지 않고는 견딜 수 없다를 나타내는 「〜ずにはいられない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n詳しく説明せ（　）、図を見れば仕組みが分かる。","options":["〜てはばからない","〜にほかならない","〜かと思えば","〜ずとも"],"answer":"〜ずとも","explanationKo":"문맥상 〜하지 않아도를 나타내는 「〜ずとも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n基本的な記録（　）残されていない。","options":["〜の至り","〜かと思うと","〜すら","〜ではあるまいし"],"answer":"〜すら","explanationKo":"문맥상 〜조차를 나타내는 「〜すら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-22','reading',1,'カテゴリーの境界を固定しない','{"passage":"対象を分類して特徴を比較することには、複雑な情報を整理し傾向を発見できることという意義がある。しかし、境界事例を無理に一つの分類へ入れると重要な差が消えることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、分類不能や複数所属を記録できる設計にすることが重要なのである。","questions":[{"prompt":"「カテゴリーの境界を固定しない」について筆者が最も重視していることは何か。","options":["分類不能や複数所属を記録できる設計にすること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"分類不能や複数所属を記録できる設計にすること","explanationKo":"본문에서는 分類不能や複数所属を記録できる設計にすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["境界事例を無理に一つの分類へ入れると重要な差が消えること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"境界事例を無理に一つの分類へ入れると重要な差が消えること","explanationKo":"주의할 점은 境界事例を無理に一つの分類へ入れると重要な差が消えること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["複雑な情報を整理し傾向を発見できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"複雑な情報を整理し傾向を発見できること","explanationKo":"対象を分類して特徴を比較すること에는 複雑な情報を整理し傾向を発見できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4221","prompt":"「易い」の読み方として最も適切なものを選びなさい。","options":["やすい","てっきり","かゆい","そのうえ"],"answer":"やすい","explanationKo":"「易い」는 「やすい」라고 읽는다. 뜻은 쉽다; ~하기 쉽다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4222","prompt":"「可愛らしい」の読み方として最も適切なものを選びなさい。","options":["このあいだ","どらい","なにげない","かわいらしい"],"answer":"かわいらしい","explanationKo":"「可愛らしい」는 「かわいらしい」라고 읽는다. 뜻은 사랑스럽다; 귀엽다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4223","prompt":"「日の丸」の読み方として最も適切なものを選びなさい。","options":["すとれす","せくしょん","ひのまる","すぴーど"],"answer":"ひのまる","explanationKo":"「日の丸」는 「ひのまる」라고 읽는다. 뜻은 일장기; 일본 국기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4224","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの駅には急行は止まらないが、（　）は停車する。","options":["荷造り","準急","ポジション","財"],"answer":"準急","explanationKo":"문맥상 「準急」가 가장 자연스럽다. 준급행; 완행보다 빠르고 급행보다 정차역이 많은 열차라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4225","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n運転中に（　）をしてはいけない。","options":["余所見","パンク","非","マッサージ"],"answer":"余所見","explanationKo":"문맥상 「余所見」가 가장 자연스럽다. 곁눈질; 한눈팔기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4226","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n眠くて（　）が重い。","options":["丈","短大","火傷","目蓋"],"answer":"目蓋","explanationKo":"문맥상 「目蓋」가 가장 자연스럽다. 눈꺼풀라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4227","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n休日なので久しぶりに（　）した。","options":["準急","同い年","朝寝坊","刺"],"answer":"朝寝坊","explanationKo":"문맥상 「朝寝坊」가 가장 자연스럽다. 늦잠; 늦잠꾸러기라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4228","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n古い建物を生かした（　）な図書館で、地域の人々にも親しまれている。","options":["面白い","素敵","何とも","各"],"answer":"素敵","explanationKo":"문맥상 「素敵」가 가장 자연스럽다. 멋지다; 훌륭하다; 근사하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4229","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）は朝晩が涼しくなり、秋らしさを感じるようになった。","options":["この頃","素敵","がっしり","痒い"],"answer":"この頃","explanationKo":"문맥상 「この頃」가 가장 자연스럽다. 요즘; 최근; 근래라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4230","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）教えてもらった店に、週末に家族と行ってみた。","options":["ロマンチック","何となく","シック","この間"],"answer":"この間","explanationKo":"문맥상 「この間」가 가장 자연스럽다. 얼마 전; 요전; 지난번라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4231","prompt":"「二つ以上のものを合わせること。また、その組み合わせ。」という意味に最も近い語を選びなさい。","options":["持ち","ネガ","合わせ","器"],"answer":"合わせ","explanationKo":"「合わせ」의 핵심 의미는 맞춤; 결합; 맞대기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4232","prompt":"「散らかった物を整理すること。また、仕事などを処理して終わらせること。」という意味に最も近い語を選びなさい。","options":["刺","片付け","トーン","増し"],"answer":"片付け","explanationKo":"「片付け」의 핵심 의미는 정리; 치우기; 마무리이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4233","prompt":"「複数の中のどれかを指す。また、将来のある時点・結局という意味でも使う。」という意味に最も近い語を選びなさい。","options":["何れ","短大","地形","釣り"],"answer":"何れ","explanationKo":"「何れ」의 핵심 의미는 어느 것이든; 언젠가; 결국이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4234","prompt":"「質問・問題などに対して示す返事・解答。」という意味に最も近い語を選びなさい。","options":["各種","見晴らし","アルミ","答え"],"answer":"答え","explanationKo":"「答え」의 핵심 의미는 답; 대답; 해답이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4235","prompt":"「容器・扉・道具などを手で持ったり開閉したりするための部分。」という意味に最も近い語を選びなさい。","options":["ファン","スペース","取っ手","話し合い"],"answer":"取っ手","explanationKo":"「取っ手」의 핵심 의미는 손잡이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','grammar',1,'〜すら','{"pattern":"〜すら","meaningKo":"〜조차","explanation":"〜すら는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"専門家ですら、その変化を予測できなかった。","ko":"문맥에서 〜조차의 의미로 쓰였다."},{"ja":"基本的な記録すら残されていない。","ko":"이 문장도 〜조차의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','grammar',2,'〜だに','{"pattern":"〜だに","meaningKo":"〜하기만 해도","explanation":"〜だに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"事故の瞬間は想像するだに恐ろしい。","ko":"문맥에서 〜하기만 해도의 의미로 쓰였다."},{"ja":"故郷の景色を思うだに胸が熱くなる。","ko":"이 문장도 〜하기만 해도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n専門家で（　）、その変化を予測できなかった。","options":["〜ではあるまいし","〜の至り","〜かと思うと","〜すら"],"answer":"〜すら","explanationKo":"문맥상 〜조차를 나타내는 「〜すら」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n事故の瞬間は想像する（　）恐ろしい。","options":["〜の極み","〜か〜ないかのうちに","〜だに","〜とあれば"],"answer":"〜だに","explanationKo":"문맥상 〜하기만 해도를 나타내는 「〜だに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n功績のある人は正当に評価され（　）である。","options":["〜そびれる","〜てしかるべき","〜とみるや","〜ばそれまでだ"],"answer":"〜てしかるべき","explanationKo":"문맥상 당연히 〜해야 한다를 나타내는 「〜てしかるべき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-23','reading',1,'データの形式と内容を分けて検証する','{"passage":"データを別の形式へ変換して利用することには、異なるシステム間で情報を共有できることという意義がある。しかし、変換が成功しても単位や文字の意味が保たれない場合があることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、件数だけでなく代表値と例外値を変換前後で照合することが重要なのである。","questions":[{"prompt":"「データの形式と内容を分けて検証する」について筆者が最も重視していることは何か。","options":["件数だけでなく代表値と例外値を変換前後で照合すること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"件数だけでなく代表値と例外値を変換前後で照合すること","explanationKo":"본문에서는 件数だけでなく代表値と例外値を変換前後で照合すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["変換が成功しても単位や文字の意味が保たれない場合があること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"変換が成功しても単位や文字の意味が保たれない場合があること","explanationKo":"주의할 점은 変換が成功しても単位や文字の意味が保たれない場合があること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["異なるシステム間で情報を共有できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"異なるシステム間で情報を共有できること","explanationKo":"データを別の形式へ変換して利用すること에는 異なるシステム間で情報を共有できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4241","prompt":"「秘書」の読み方として最も適切なものを選びなさい。","options":["つくり","ひしょ","かたづけ","あこがれ"],"answer":"ひしょ","explanationKo":"「秘書」는 「ひしょ」라고 읽는다. 뜻은 비서이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4242","prompt":"「原子」の読み方として最も適切なものを選びなさい。","options":["げんし","めつき","いん","しょっく"],"answer":"げんし","explanationKo":"「原子」는 「げんし」라고 읽는다. 뜻은 원자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4243","prompt":"「各種」の読み方として最も適切なものを選びなさい。","options":["めーかー","ぶーむ","こんとらすと","かくしゅ"],"answer":"かくしゅ","explanationKo":"「各種」는 「かくしゅ」라고 읽는다. 뜻은 각종; 여러 종류이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4244","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n今日は（　）予定がない。","options":["済まない","雑","何も","段々"],"answer":"何も","explanationKo":"문맥상 「何も」가 가장 자연스럽다. 아무것도; 아무것도 특별히라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',5,'文字・語彙','{"type":"context_fill","wordKey":"n1-4245","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n私は（　）会議室へ行って準備しておきます。","options":["お洒落","先に","ユニーク","がっちり"],"answer":"先に","explanationKo":"문맥상 「先に」가 가장 자연스럽다. 먼저; 앞서; 이전에라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4246","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は舞台で重要な役を（　）。","options":["演ずる","落とす","曲がる","出合う"],"answer":"演ずる","explanationKo":"문맥상 「演ずる」가 가장 자연스럽다. 연기하다; 연주하다; 역할을 하다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4247","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの部屋は広く、（　）、駅にも近い。","options":["素敵","てっきり","痒い","その上"],"answer":"その上","explanationKo":"문맥상 「その上」가 가장 자연스럽다. 게다가; 그뿐만 아니라; 또한라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4248","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの会社は社員の自主性を（　）。","options":["起こす","捲る","重んずる","何と"],"answer":"重んずる","explanationKo":"문맥상 「重んずる」가 가장 자연스럽다. 중시하다; 존중하다; 소중히 여기다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4249","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n締め切りが（　）につれて、問い合わせが増えてきた。","options":["背負う","近付く","織る","捲る"],"answer":"近付く","explanationKo":"문맥상 「近付く」가 가장 자연스럽다. 다가가다; 가까워지다; 친해지다라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4250","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）今日はいいことがありそうな気がする。","options":["何となく","大人しい","ドライ","割合に"],"answer":"何となく","explanationKo":"문맥상 「何となく」가 가장 자연스럽다. 왠지; 어쩐지; 특별한 이유 없이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4251","prompt":"「言葉ではうまく表せないほど。また、否定表現とともに『少しも・何も』の意を表す。」という意味に最も近い語を選びなさい。","options":["先に","易い","ユニーク","何とも"],"answer":"何とも","explanationKo":"「何とも」의 핵심 의미는 뭐라고도; 정말; 아무렇지도이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4252","prompt":"「服装などに気を配って洗練されていること。また、そのような人。」という意味に最も近い語を選びなさい。","options":["面白い","ひょっと","お洒落","グレー"],"answer":"お洒落","explanationKo":"「お洒落」의 핵심 의미는 멋내기; 세련됨; 멋쟁이이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4253","prompt":"「特別な意図・関心がないように見えるさま。」という意味に最も近い語を選びなさい。","options":["段々","何気ない","お洒落","タイムリー"],"answer":"何気ない","explanationKo":"「何気ない」의 핵심 의미는 무심한; 아무렇지 않은; 별 뜻 없는이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4254","prompt":"「体に傷を負う。また、心・名誉・物などが損なわれる。」という意味に最も近い語を選びなさい。","options":["傷付く","跨がる","老ける","解く"],"answer":"傷付く","explanationKo":"「傷付く」의 핵심 의미는 상처 입다; 다치다; 마음에 상처를 받다; 손상되다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4255","prompt":"「愚かで、まともに取り合う価値がないと感じられる。」という意味に最も近い語を選びなさい。","options":["各","直ぐ","がっしり","馬鹿らしい"],"answer":"馬鹿らしい","explanationKo":"「馬鹿らしい」의 핵심 의미는 바보같다; 어처구니없다; 시시하다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','grammar',1,'〜てしかるべき','{"pattern":"〜てしかるべき","meaningKo":"당연히 〜해야 한다","explanation":"〜てしかるべき는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"重大な変更は事前に説明されてしかるべきだ。","ko":"문맥에서 당연히 〜해야 한다의 의미로 쓰였다."},{"ja":"功績のある人は正当に評価されてしかるべきである。","ko":"이 문장도 당연히 〜해야 한다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','grammar',2,'〜てはかなわない','{"pattern":"〜てはかなわない","meaningKo":"〜해서는 견딜 수 없다","explanation":"〜てはかなわない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"毎晩工事の音が続いてはかなわない。","ko":"문맥에서 〜해서는 견딜 수 없다의 의미로 쓰였다."},{"ja":"同じ資料を何度も提出させられてはかなわない。","ko":"이 문장도 〜해서는 견딜 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n重大な変更は事前に説明され（　）だ。","options":["〜ばそれまでだ","〜そびれる","〜てしかるべき","〜とみるや"],"answer":"〜てしかるべき","explanationKo":"문맥상 당연히 〜해야 한다를 나타내는 「〜てしかるべき」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n毎晩工事の音が続い（　）。","options":["〜きれない","〜てはかなわない","〜ないまでも","〜まみれ"],"answer":"〜てはかなわない","explanationKo":"문맥상 〜해서는 견딜 수 없다를 나타내는 「〜てはかなわない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nその企業は業界を変えると宣言し（　）。","options":["〜てはばからない","〜にあらず","〜めく","〜かねない"],"answer":"〜てはばからない","explanationKo":"문맥상 거리낌 없이 〜하다를 나타내는 「〜てはばからない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-24','reading',1,'コミュニケーションの量を成果にしない','{"passage":"組織内の連絡回数や会議時間を測ることには、情報共有の停滞を見つける手掛かりになることという意義がある。しかし、回数を増やすだけでは理解や意思決定が改善しないことには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、必要な相手が次の行動を選べたかで伝達を評価することが重要なのである。","questions":[{"prompt":"「コミュニケーションの量を成果にしない」について筆者が最も重視していることは何か。","options":["必要な相手が次の行動を選べたかで伝達を評価すること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"必要な相手が次の行動を選べたかで伝達を評価すること","explanationKo":"본문에서는 必要な相手が次の行動を選べたかで伝達を評価すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["回数を増やすだけでは理解や意思決定が改善しないこと","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"回数を増やすだけでは理解や意思決定が改善しないこと","explanationKo":"주의할 점은 回数を増やすだけでは理解や意思決定が改善しないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["情報共有の停滞を見つける手掛かりになること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"情報共有の停滞を見つける手掛かりになること","explanationKo":"組織内の連絡回数や会議時間を測ること에는 情報共有の停滞を見つける手掛かりになること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4261","prompt":"「当て」の読み方として最も適切なものを選びなさい。","options":["わび","としより","あて","ひかえしつ"],"answer":"あて","explanationKo":"「当て」는 「あて」라고 읽는다. 뜻은 기대; 의지할 곳; 목표·예상이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
