INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4263","prompt":"「当たり」の読み方として最も適切なものを選びなさい。","options":["あたり","るーる","しなりお","ぱとかー"],"answer":"あたり","explanationKo":"「当たり」는 「あたり」라고 읽는다. 뜻은 적중; 당첨; ~당; 접촉·반응이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
