INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4270","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n引っ越し前日に夜遅くまで（　）をした。","options":["コマーシャル","荷造り","メーカー","ブーム"],"answer":"荷造り","explanationKo":"문맥상 「荷造り」가 가장 자연스럽다. 짐 싸기; 포장라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4271","prompt":"「役所・組織などに一定の事実を知らせること。また、その書類。」という意味に最も近い語を選びなさい。","options":["届け","朝寝坊","コンタクト","壇"],"answer":"届け","explanationKo":"「届け」의 핵심 의미는 신고; 신고서; 통지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4272","prompt":"「人を招くこと。招待。」という意味に最も近い語を選びなさい。","options":["矢","腿","地形","招き"],"answer":"招き","explanationKo":"「招き」의 핵심 의미는 초대; 초청; 부름이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4273","prompt":"「自分の過失などについて謝ること。また、その言葉。」という意味に最も近い語を選びなさい。","options":["釣り","届け","詫び","一人"],"answer":"詫び","explanationKo":"「詫び」의 핵심 의미는 사과; 사죄이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4274","prompt":"「長い間、訪問・連絡・便りなどをしないでいること。」という意味に最も近い語を選びなさい。","options":["出入り口","ご無沙汰","目蓋","当て"],"answer":"ご無沙汰","explanationKo":"「ご無沙汰」의 핵심 의미는 오랫동안 연락하지 못함; 오래 찾아뵙지 못함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4275","prompt":"「商品を売り始めること。また、特別に値段を下げて大量に販売すること。」という意味に最も近い語を選びなさい。","options":["売り出し","印","ショック","タイミング"],"answer":"売り出し","explanationKo":"「売り出し」의 핵심 의미는 판매 개시; 특매; 세일이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','grammar',1,'〜てはばからない','{"pattern":"〜てはばからない","meaningKo":"거리낌 없이 〜하다","explanation":"〜てはばからない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"彼は自分こそ適任だと公言してはばからない。","ko":"문맥에서 거리낌 없이 〜하다의 의미로 쓰였다."},{"ja":"その企業は業界を変えると宣言してはばからない。","ko":"이 문장도 거리낌 없이 〜하다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','grammar',2,'〜ではあるまいし','{"pattern":"〜ではあるまいし","meaningKo":"〜도 아닐 텐데","explanation":"〜ではあるまいし는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"子どもではあるまいし、責任を人に押しつけるべきではない。","ko":"문맥에서 〜도 아닐 텐데의 의미로 쓰였다."},{"ja":"初めてではあるまいし、手順を確認してから始めてほしい。","ko":"이 문장도 〜도 아닐 텐데의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n彼は自分こそ適任だと公言し（　）。","options":["〜かねない","〜てはばからない","〜にあらず","〜めく"],"answer":"〜てはばからない","explanationKo":"문맥상 거리낌 없이 〜하다를 나타내는 「〜てはばからない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n子ども（　）、責任を人に押しつけるべきではない。","options":["〜ではあるまいし","〜にほかならない","〜をいいことに","〜かねる"],"answer":"〜ではあるまいし","explanationKo":"문맥상 〜도 아닐 텐데를 나타내는 「〜ではあるまいし」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n信頼回復につながる（　）、情報を公開する用意がある。","options":["〜の至り","〜を禁じ得ない","〜ざるを得ない","〜とあれば"],"answer":"〜とあれば","explanationKo":"문맥상 〜라면를 나타내는 「〜とあれば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-25','reading',1,'ストレスを個人の弱さに還元しない','{"passage":"働く人の心理的負担を調べることには、健康上の問題を早く発見し支援できることという意義がある。しかし、本人の性格だけを原因にすると業務量や裁量の不足を見落とすことには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、個人支援と同時に仕事の構造と資源配分を見直すことが重要なのである。","questions":[{"prompt":"「ストレスを個人の弱さに還元しない」について筆者が最も重視していることは何か。","options":["個人支援と同時に仕事の構造と資源配分を見直すこと","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"個人支援と同時に仕事の構造と資源配分を見直すこと","explanationKo":"본문에서는 個人支援と同時に仕事の構造と資源配分を見直すこと 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["本人の性格だけを原因にすると業務量や裁量の不足を見落とすこと","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"本人の性格だけを原因にすると業務量や裁量の不足を見落とすこと","explanationKo":"주의할 점은 本人の性格だけを原因にすると業務量や裁量の不足を見落とすこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["健康上の問題を早く発見し支援できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"健康上の問題を早く発見し支援できること","explanationKo":"働く人の心理的負担を調べること에는 健康上の問題を早く発見し支援できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4281","prompt":"「勤め先」の読み方として最も適切なものを選びなさい。","options":["ひしょ","よふけ","めでぃあ","つとめさき"],"answer":"つとめさき","explanationKo":"「勤め先」는 「つとめさき」라고 읽는다. 뜻은 직장; 근무처이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
