INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4286","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は肩幅が広く、（　）した体格をしている。","options":["及び","何となく","がっちり","甘い"],"answer":"がっちり","explanationKo":"문맥상 「がっちり」가 가장 자연스럽다. 튼튼하게; 단단히; 야무지게; 체격이 다부지게라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4287","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）今日が締切だと思っていた。","options":["グレー","てっきり","段々","夜中"],"answer":"てっきり","explanationKo":"문맥상 「てっきり」가 가장 자연스럽다. 틀림없이 ~라고 생각하다; 영락없이라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4288","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は（　）した体格をしている。","options":["がっしり","当たり前","何とも","素敵"],"answer":"がっしり","explanationKo":"문맥상 「がっしり」가 가장 자연스럽다. 튼튼하게; 건장하게; 다부지게라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4289","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は知らない（　）をして、その場を通り過ぎた。","options":["ベスト","トラブル","コマーシャル","振り"],"answer":"振り","explanationKo":"문맥상 「振り」가 가장 자연스럽다. 척; 시늉; 태도; 모습라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4290","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）が続くと朝起きるのがつらい。","options":["シナリオ","ダンプ","夜更かし","ルール"],"answer":"夜更かし","explanationKo":"문맥상 「夜更かし」가 가장 자연스럽다. 밤늦게까지 깨어 있음; 밤샘라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4291","prompt":"「ある内容を否定すること。文法では否定表現を指す。」という意味に最も近い語を選びなさい。","options":["桐","打ち消し","荷造り","カルテ"],"answer":"打ち消し","explanationKo":"「打ち消し」의 핵심 의미는 부정; 부인; 취소이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4292","prompt":"「目に表れる表情や視線の様子。」という意味に最も近い語を選びなさい。","options":["目付き","膳","織","中指"],"answer":"目付き","explanationKo":"「目付き」의 핵심 의미는 눈빛; 눈매; 눈의 표정이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4293","prompt":"「複数の事柄を並べて結ぶ語。『そして』『ならびに』の意。」という意味に最も近い語を選びなさい。","options":["素敵","がっちり","痒い","及び"],"answer":"及び","explanationKo":"「及び」의 핵심 의미는 및; 그리고이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4294","prompt":"「眠っている人を目覚めさせたり、物事・現象・事件などを生じさせたりする。」という意味に最も近い語を選びなさい。","options":["老ける","解く","起こす","跨がる"],"answer":"起こす","explanationKo":"「起こす」의 핵심 의미는 일으키다; 발생시키다; 깨우다이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4295","prompt":"「特に不思議ではなく、当然であること。また、普通であること。」という意味に最も近い語を選びなさい。","options":["この頃","当たり前","何だかんだ","シック"],"answer":"当たり前","explanationKo":"「当たり前」의 핵심 의미는 당연함; 당연한; 보통의이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','grammar',1,'〜とあれば','{"pattern":"〜とあれば","meaningKo":"〜라면","explanation":"〜とあれば는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"住民の安全のためとあれば、計画の変更も必要だ。","ko":"문맥에서 〜라면의 의미로 쓰였다."},{"ja":"信頼回復につながるとあれば、情報を公開する用意がある。","ko":"이 문장도 〜라면의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','grammar',2,'〜とみるや','{"pattern":"〜とみるや","meaningKo":"〜라고 보자마자","explanation":"〜とみるや는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"危険だとみるや、係員は直ちに会場を閉鎖した。","ko":"문맥에서 〜라고 보자마자의 의미로 쓰였다."},{"ja":"勝機があるとみるや、監督は攻撃的な選手を投入した。","ko":"이 문장도 〜라고 보자마자의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n住民の安全のため（　）、計画の変更も必要だ。","options":["〜とあれば","〜の至り","〜を禁じ得ない","〜ざるを得ない"],"answer":"〜とあれば","explanationKo":"문맥상 〜라면를 나타내는 「〜とあれば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n危険だ（　）、係員は直ちに会場を閉鎖した。","options":["〜の極み","〜かと思えば","〜ずにはいられない","〜とみるや"],"answer":"〜とみるや","explanationKo":"문맥상 〜라고 보자마자를 나타내는 「〜とみるや」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n毎日で（　）、定期的に記録を確認すべきだ。","options":["〜かと思うと","〜ずとも","〜ないまでも","〜ばそれまでだ"],"answer":"〜ないまでも","explanationKo":"문맥상 〜까지는 아니더라도를 나타내는 「〜ないまでも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-26','reading',1,'シナリオを予言として扱わない','{"passage":"複数の将来像を作って対応を考えることには、不確実な状況でも選択肢と準備を比較できることという意義がある。しかし、一つの筋書きを確定予測と誤解すると変化への対応が遅れることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、前提が崩れた時に別の行動へ切り替える条件を定めることが重要なのである。","questions":[{"prompt":"「シナリオを予言として扱わない」について筆者が最も重視していることは何か。","options":["前提が崩れた時に別の行動へ切り替える条件を定めること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"前提が崩れた時に別の行動へ切り替える条件を定めること","explanationKo":"본문에서는 前提が崩れた時に別の行動へ切り替える条件を定めること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["一つの筋書きを確定予測と誤解すると変化への対応が遅れること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"一つの筋書きを確定予測と誤解すると変化への対応が遅れること","explanationKo":"주의할 점은 一つの筋書きを確定予測と誤解すると変化への対応が遅れること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["不確実な状況でも選択肢と準備を比較できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"不確実な状況でも選択肢と準備を比較できること","explanationKo":"複数の将来像を作って対応を考えること에는 不確実な状況でも選択肢と準備を比較できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4301","prompt":"「持ち」の読み方として最も適切なものを選びなさい。","options":["もち","つり","てあて","うちけし"],"answer":"もち","explanationKo":"「持ち」는 「もち」라고 읽는다. 뜻은 지속성; 오래감; 보유·담당이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4302","prompt":"「調べ」の読み方として最も適切なものを選びなさい。","options":["あるみ","ほーる","たいとる","しらべ"],"answer":"しらべ","explanationKo":"「調べ」는 「しらべ」라고 읽는다. 뜻은 조사; 조사함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4303","prompt":"「知り合い」の読み方として最も適切なものを選びなさい。","options":["らべる","はつ","しりあい","すぺーす"],"answer":"しりあい","explanationKo":"「知り合い」는 「しりあい」라고 읽는다. 뜻은 지인; 아는 사람이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4304","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nこの地域では、一人暮らしの（　）を近所で見守る取り組みが続けられている。","options":["ダンプ","年寄り","版","手当て"],"answer":"年寄り","explanationKo":"문맥상 「年寄り」가 가장 자연스럽다. 노인; 나이 든 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
