INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4306","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n一方的に決めるのではなく、当事者同士の（　）で解決策を探すべきだ。","options":["腿","地形","肉体","話し合い"],"answer":"話し合い","explanationKo":"문맥상 「話し合い」가 가장 자연스럽다. 대화; 협의; 논의라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4307","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は仕事上の判断ではかなり（　）で、個人的な感情を持ち込まない。","options":["がっちり","甘い","ドライ","可愛らしい"],"answer":"ドライ","explanationKo":"문맥상 「ドライ」가 가장 자연스럽다. 건조한; 드라이한; 냉정하고 담백한라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4308","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n店内は黒を基調とした（　）な雰囲気だった。","options":["グレー","シック","雑","先に"],"answer":"シック","explanationKo":"문맥상 「シック」가 가장 자연스럽다. 세련된; 차분하고 멋진라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4309","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n規則上は完全に禁止ではないが、かなり（　）なケースだ。","options":["グレー","ドライ","段々","割合に"],"answer":"グレー","explanationKo":"문맥상 「グレー」가 가장 자연스럽다. 회색; 애매한 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4310","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n彼は今季からチームの（　）に選ばれた。","options":["何気ない","各","可愛らしい","レギュラー"],"answer":"レギュラー","explanationKo":"문맥상 「レギュラー」가 가장 자연스럽다. 정규; 주전; 레귤러라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4311","prompt":"「他にはあまりなく、独特で個性的なさま。」という意味に最も近い語を選びなさい。","options":["何気ない","素敵","ユニーク","大人しい"],"answer":"ユニーク","explanationKo":"「ユニーク」의 핵심 의미는 독특함; 유니크함이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4312","prompt":"「意味がなく、常識に合わないこと。」という意味に最も近い語を選びなさい。","options":["がっちり","ナンセンス","雑","素敵"],"answer":"ナンセンス","explanationKo":"「ナンセンス」의 핵심 의미는 난센스; 터무니없음이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4313","prompt":"「時機に合っていて、ちょうどよいさま。」という意味に最も近い語を選びなさい。","options":["タイムリー","馬鹿らしい","当たり前","可愛らしい"],"answer":"タイムリー","explanationKo":"「タイムリー」의 핵심 의미는 시기적절한; 적시에 맞는이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4314","prompt":"「上昇・増加を表す語。また、アップロード・クローズアップ・ウォームアップなどの略としても使う。」という意味に最も近い語を選びなさい。","options":["夜更け","メディア","サイズ","アップ"],"answer":"アップ","explanationKo":"「アップ」의 핵심 의미는 상승; 증가; 업로드·클로즈업 등의 ''업''이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4315","prompt":"「情報・意見などを多くの人に伝える媒体・手段。新聞、テレビ、インターネットなど。」という意味に最も近い語を選びなさい。","options":["コーナー","ジャンル","メディア","ポイント"],"answer":"メディア","explanationKo":"「メディア」의 핵심 의미는 미디어; 매체이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','grammar',1,'〜ないまでも','{"pattern":"〜ないまでも","meaningKo":"〜까지는 아니더라도","explanation":"〜ないまでも는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"完璧でないまでも、実用に耐える水準には達した。","ko":"문맥에서 〜까지는 아니더라도의 의미로 쓰였다."},{"ja":"毎日でないまでも、定期的に記録を確認すべきだ。","ko":"이 문장도 〜까지는 아니더라도의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','grammar',2,'〜にあらず','{"pattern":"〜にあらず","meaningKo":"〜이 아니다","explanation":"〜にあらず는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"問題は費用にあらず、責任の所在にある。","ko":"문맥에서 〜이 아니다의 의미로 쓰였다."},{"ja":"目的は批判にあらず、再発を防ぐことだ。","ko":"이 문장도 〜이 아니다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n完璧で（　）、実用に耐える水準には達した。","options":["〜ばそれまでだ","〜かと思うと","〜ずとも","〜ないまでも"],"answer":"〜ないまでも","explanationKo":"문맥상 〜까지는 아니더라도를 나타내는 「〜ないまでも」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n問題は費用（　）、責任の所在にある。","options":["〜か〜ないかのうちに","〜すら","〜にあらず","〜まみれ"],"answer":"〜にあらず","explanationKo":"문맥상 〜이 아니다를 나타내는 「〜にあらず」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこの結果は準備不足の表れ（　）。","options":["〜だに","〜にほかならない","〜めく","〜そびれる"],"answer":"〜にほかならない","explanationKo":"문맥상 다름 아닌 〜이다를 나타내는 「〜にほかならない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-27','reading',1,'オンライン参加の見えない障壁','{"passage":"会議や手続きをオンラインで提供することには、距離にかかわらず参加する機会を広げられることという意義がある。しかし、端末や通信環境や操作能力の差で利用できない人が生じることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、代替手段と支援窓口を残して実際の利用率を確かめることが重要なのである。","questions":[{"prompt":"「オンライン参加の見えない障壁」について筆者が最も重視していることは何か。","options":["代替手段と支援窓口を残して実際の利用率を確かめること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"代替手段と支援窓口を残して実際の利用率を確かめること","explanationKo":"본문에서는 代替手段と支援窓口を残して実際の利用率を確かめること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["端末や通信環境や操作能力の差で利用できない人が生じること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"端末や通信環境や操作能力の差で利用できない人が生じること","explanationKo":"주의할 점은 端末や通信環境や操作能力の差で利用できない人が生じること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["距離にかかわらず参加する機会を広げられること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"距離にかかわらず参加する機会を広げられること","explanationKo":"会議や手続きをオンラインで提供すること에는 距離にかかわらず参加する機会を広げられること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4321","prompt":"「乙」の読み方として最も適切なものを選びなさい。","options":["このごろ","おつ","なんだかんだ","いんたーなしょなる"],"answer":"おつ","explanationKo":"「乙」는 「おつ」라고 읽는다. 뜻은 을; 둘째 등급; 색다르고 멋스러움이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',2,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4322","prompt":"「巻」の読み方として最も適切なものを選びなさい。","options":["まき","ぎょう","がいど","おんらいん"],"answer":"まき","explanationKo":"「巻」는 「まき」라고 읽는다. 뜻은 권; 책의 권 또는 두루마리이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',3,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4323","prompt":"「行」の読み方として最も適切なものを選びなさい。","options":["とらぶる","こまーしゃる","なん","ぎょう"],"answer":"ぎょう","explanationKo":"「行」는 「ぎょう」라고 읽는다. 뜻은 행; 글의 줄; 수행이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4324","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n申請書の指定欄に（　）を押して提出してください。","options":["夜更かし","ドリル","印","非"],"answer":"印","explanationKo":"문맥상 「印」가 가장 자연스럽다. 인장; 도장; 표식라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
