INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4326","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）を尽くして説明すれば、相手にもこちらの考えが伝わるだろう。","options":["誠","織","中指","各種"],"answer":"誠","explanationKo":"문맥상 「誠」가 가장 자연스럽다. 진심; 성의; 진실라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4327","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n物語では人間の姿をした（　）が森の奥に住んでいると語られる。","options":["教科","顔付き","話し合い","獣"],"answer":"獣","explanationKo":"문맥상 「獣」가 가장 자연스럽다. 짐승; 야수; 비유적으로 인간답지 못한 사람라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4328","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n（　）な環境で働いている。","options":["グレー","一定","インターナショナル","先に"],"answer":"インターナショナル","explanationKo":"문맥상 「インターナショナル」가 가장 자연스럽다. 국제적인; 국제적라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4329","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n夜景の見えるレストランで（　）な時間を過ごした。","options":["乙","ロマンチック","痒い","お洒落"],"answer":"ロマンチック","explanationKo":"문맥상 「ロマンチック」가 가장 자연스럽다. 낭만적; 로맨틱함라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4330","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n新しい勤怠（　）の導入に伴い、申請手順も変更された。","options":["システム","パトカー","捕鯨","コントロール"],"answer":"システム","explanationKo":"문맥상 「システム」가 가장 자연스럽다. 시스템; 체계; 제도라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
