INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4332","prompt":"「利益を目的とする事業・商取引。また、仕事上の活動。」という意味に最も近い語を選びなさい。","options":["金庫","答え","ビジネス","藁"],"answer":"ビジネス","explanationKo":"「ビジネス」의 핵심 의미는 사업; 비즈니스; 업무이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4333","prompt":"「調査・分析・判断の基礎となる数値や事実などの情報。コンピューターで処理される情報もいう。」という意味に最も近い語を選びなさい。","options":["目付き","データ","目蓋","掛け"],"answer":"データ","explanationKo":"「データ」의 핵심 의미는 데이터; 자료이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
