INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','grammar',1,'〜にほかならない','{"pattern":"〜にほかならない","meaningKo":"다름 아닌 〜이다","explanation":"〜にほかならない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"成功の理由は、現場の地道な努力にほかならない。","ko":"문맥에서 다름 아닌 〜이다의 의미로 쓰였다."},{"ja":"この結果は準備不足の表れにほかならない。","ko":"이 문장도 다름 아닌 〜이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','grammar',2,'〜の至り','{"pattern":"〜の至り","meaningKo":"지극한 〜","explanation":"〜の至り는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"このような評価をいただき、光栄の至りです。","ko":"문맥에서 지극한 〜의 의미로 쓰였다."},{"ja":"ご迷惑をおかけし、恐縮の至りでございます。","ko":"이 문장도 지극한 〜의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n成功の理由は、現場の地道な努力（　）。","options":["〜そびれる","〜だに","〜にほかならない","〜めく"],"answer":"〜にほかならない","explanationKo":"문맥상 다름 아닌 〜이다를 나타내는 「〜にほかならない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\nこのような評価をいただき、光栄（　）です。","options":["〜てしかるべき","〜の至り","〜をいいことに","〜きれない"],"answer":"〜の至り","explanationKo":"문맥상 지극한 〜를 나타내는 「〜の至り」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n長年の夢が実現し、感激（　）である。","options":["〜の極み","〜を禁じ得ない","〜かねない","〜てはかなわない"],"answer":"〜の極み","explanationKo":"문맥상 더할 나위 없는 〜를 나타내는 「〜の極み」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-02-28','reading',1,'ラベルが判断を先取りする','{"passage":"対象に短い名称や評価を付けることには、特徴を素早く共有し整理できることという意義がある。しかし、名称から抱く印象が個別の事実を見る前に判断を固定することには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、ラベルの定義と根拠を示し更新可能にすることが重要なのである。","questions":[{"prompt":"「ラベルが判断を先取りする」について筆者が最も重視していることは何か。","options":["ラベルの定義と根拠を示し更新可能にすること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"ラベルの定義と根拠を示し更新可能にすること","explanationKo":"본문에서는 ラベルの定義と根拠を示し更新可能にすること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["名称から抱く印象が個別の事実を見る前に判断を固定すること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"名称から抱く印象が個別の事実を見る前に判断を固定すること","explanationKo":"주의할 점은 名称から抱く印象が個別の事実を見る前に判断を固定すること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["特徴を素早く共有し整理できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"特徴を素早く共有し整理できること","explanationKo":"対象に短い名称や評価を付けること에는 特徴を素早く共有し整理できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
