INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',4,'文字・語彙','{"type":"context_fill","wordKey":"n1-4344","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n初めて利用する人向けに、設定手順をまとめた（　）が公開されている。","options":["デッサン","デザイン","ミスプリント","ガイド"],"answer":"ガイド","explanationKo":"문맥상 「ガイド」가 가장 자연스럽다. 가이드; 안내자; 안내서라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
