INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',6,'文字・語彙','{"type":"context_fill","wordKey":"n1-4346","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n運用（　）を曖昧なままにすると、担当者ごとに判断が変わってしまう。","options":["当たり","ルール","雫","準急"],"answer":"ルール","explanationKo":"문맥상 「ルール」가 가장 자연스럽다. 규칙; 룰라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',7,'文字・語彙','{"type":"context_fill","wordKey":"n1-4347","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n重要な項目には赤い（　）を付け、確認漏れを防ぐようにした。","options":["マーク","汚れ","出入り口","アクセル"],"answer":"マーク","explanationKo":"문맥상 「マーク」가 가장 자연스럽다. 표시; 표식; 마크라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',8,'文字・語彙','{"type":"context_fill","wordKey":"n1-4348","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n作業台が汚れないように、透明な保護（　）を敷いた。","options":["アップ","スピード","センス","シート"],"answer":"シート","explanationKo":"문맥상 「シート」가 가장 자연스럽다. 좌석; 시트; 얇은 판·천라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4349","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n駅前に新しい商業施設が来月（　）する予定だ。","options":["ガイド","オンライン","オープン","行"],"answer":"オープン","explanationKo":"문맥상 「オープン」가 가장 자연스럽다. 개장; 개점; 공개; 열린 상태라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4350","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\nその数字を資料に使う前に、情報の（　）が信頼できるか確認した。","options":["マッサージ","ソース","実","付き"],"answer":"ソース","explanationKo":"문맥상 「ソース」가 가장 자연스럽다. 출처; 정보원; 소스라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4351","prompt":"「相手に伝える言葉・内容・意図。また、通信手段で送る短い文章。」という意味に最も近い語を選びなさい。","options":["メッセージ","キャッチ","婿","セレモニー"],"answer":"メッセージ","explanationKo":"「メッセージ」의 핵심 의미는 메시지; 전달 내용; 전언이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4352","prompt":"「言葉・文字・表情などを通して、情報・考え・感情を互いに伝え合うこと。」という意味に最も近い語を選びなさい。","options":["檻","木綿","昼間","コミュニケーション"],"answer":"コミュニケーション","explanationKo":"「コミュニケーション」의 핵심 의미는 의사소통; 커뮤니케이션이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4353","prompt":"「切ること・切り取ること。髪を切ること、映像の一場面、内容や費用などを削ることにも用いる。」という意味に最も近い語を選びなさい。","options":["合わせ","当たり","カット","空間"],"answer":"カット","explanationKo":"「カット」의 핵심 의미는 자르기; 삭제; 삭감; 컷이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4354","prompt":"「範囲・幅。また、加熱調理に用いるレンジ・電子レンジなどの調理器具。」という意味に最も近い語を選びなさい。","options":["ルール","レンジ","錆び","柱"],"answer":"レンジ","explanationKo":"「レンジ」의 핵심 의미는 범위; 레인지; 조리기기이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4355","prompt":"「機能・状態・数値などが下がること、または停止すること。競技で倒れることなどにも用いる。」という意味に最も近い語を選びなさい。","options":["ダウン","年寄り","ファイル","レンジ"],"answer":"ダウン","explanationKo":"「ダウン」의 핵심 의미는 다운; 정지; 쓰러짐; 저하이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','grammar',1,'〜の極み','{"pattern":"〜の極み","meaningKo":"더할 나위 없는 〜","explanation":"〜の極み는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"支援を受けながら報告を怠るとは、無責任の極みだ。","ko":"문맥에서 더할 나위 없는 〜의 의미로 쓰였다."},{"ja":"長年の夢が実現し、感激の極みである。","ko":"이 문장도 더할 나위 없는 〜의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','grammar',2,'〜ばそれまでだ','{"pattern":"〜ばそれまでだ","meaningKo":"〜하면 그것으로 끝이다","explanation":"〜ばそれまでだ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"記録が正しくても、誰も読まなければそれまでだ。","ko":"문맥에서 〜하면 그것으로 끝이다의 의미로 쓰였다."},{"ja":"便利な制度も、利用できる人がいなければそれまでだ。","ko":"이 문장도 〜하면 그것으로 끝이다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n支援を受けながら報告を怠るとは、無責任（　）だ。","options":["〜てはかなわない","〜の極み","〜を禁じ得ない","〜かねない"],"answer":"〜の極み","explanationKo":"문맥상 더할 나위 없는 〜를 나타내는 「〜の極み」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
