INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n選手は泥（　）になって最後まで走った。","options":["〜かと思うと","〜ざるを得ない","〜ではあるまいし","〜まみれ"],"answer":"〜まみれ","explanationKo":"문맥상 〜투성이를 나타내는 「〜まみれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-01','reading',1,'専門用語の略称を管理する','{"passage":"長い名称を略して文書や会話で使うことには、情報を簡潔に伝え作業を速められることという意義がある。しかし、分野ごとに同じ略称が別の意味を持つと誤解が生じることには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、初出で正式名称を示し文書内の対応を一貫させることが重要なのである。","questions":[{"prompt":"「専門用語の略称を管理する」について筆者が最も重視していることは何か。","options":["初出で正式名称を示し文書内の対応を一貫させること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"初出で正式名称を示し文書内の対応を一貫させること","explanationKo":"본문에서는 初出で正式名称を示し文書内の対応を一貫させること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["分野ごとに同じ略称が別の意味を持つと誤解が生じること","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"分野ごとに同じ略称が別の意味を持つと誤解が生じること","explanationKo":"주의할 점은 分野ごとに同じ略称が別の意味を持つと誤解が生じること 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["情報を簡潔に伝え作業を速められること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"情報を簡潔に伝え作業を速められること","explanationKo":"長い名称を略して文書や会話で使うこと에는 情報を簡潔に伝え作業を速められること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4361","prompt":"「トラブル」の読み方として最も適切なものを選びなさい。","options":["かおつき","はなしあい","ふぁん","とらぶる"],"answer":"とらぶる","explanationKo":"「トラブル」는 「とらぶる」라고 읽는다. 뜻은 문제; 말썽; 분쟁; 고장이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
