INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4371","prompt":"「ホテルなどの受付。また、物の前面。」という意味に最も近い語を選びなさい。","options":["濠","フロント","ダンプ","裾"],"answer":"フロント","explanationKo":"「フロント」의 핵심 의미는 프런트; 접수대; 전면이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4372","prompt":"「招かれた客。また、番組などに招待されて出演する人。」という意味に最も近い語を選びなさい。","options":["ゲスト","襟","一日","原子"],"answer":"ゲスト","explanationKo":"「ゲスト」의 핵심 의미는 손님; 게스트; 초대 출연자이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4373","prompt":"「コンピューターなどの映像を表示する画面・装置。」という意味に最も近い語を選びなさい。","options":["肉体","売り出し","仕上げ","モニター"],"answer":"モニター","explanationKo":"「モニター」의 핵심 의미는 모니터; 화면이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4374","prompt":"「一定の変化を経て元の状態に戻るまでの一巡り。」という意味に最も近い語を選びなさい。","options":["ビジネス","メッセージ","サイクル","調べ"],"answer":"サイクル","explanationKo":"「サイクル」의 핵심 의미는 사이클; 주기; 순환이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4375","prompt":"「位置・立場・役割。特にスポーツで選手が担当する位置や役割。」という意味に最も近い語を選びなさい。","options":["源","ポジション","マーク","フォーム"],"answer":"ポジション","explanationKo":"「ポジション」의 핵심 의미는 포지션; 위치; 역할이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','grammar',1,'〜まみれ','{"pattern":"〜まみれ","meaningKo":"〜투성이","explanation":"〜まみれ는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"倉庫から、ほこりまみれの資料が見つかった。","ko":"문맥에서 〜투성이의 의미로 쓰였다."},{"ja":"選手は泥まみれになって最後まで走った。","ko":"이 문장도 〜투성이의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','grammar',2,'〜めく','{"pattern":"〜めく","meaningKo":"〜스러워지다","explanation":"〜めく는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"日差しが柔らかくなり、急に春めいてきた。","ko":"문맥에서 〜스러워지다의 의미로 쓰였다."},{"ja":"彼の説明は次第に言い訳めいてきた。","ko":"이 문장도 〜스러워지다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n倉庫から、ほこり（　）の資料が見つかった。","options":["〜まみれ","〜かと思うと","〜ざるを得ない","〜ではあるまいし"],"answer":"〜まみれ","explanationKo":"문맥상 〜투성이를 나타내는 「〜まみれ」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n日差しが柔らかくなり、急に春（　）きた。","options":["〜か〜ないかのうちに","〜ずにはいられない","〜とあれば","〜めく"],"answer":"〜めく","explanationKo":"문맥상 〜스러워지다를 나타내는 「〜めく」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n相手が反論しないの（　）、責任を押しつけた。","options":["〜ずとも","〜とみるや","〜をいいことに","〜そびれる"],"answer":"〜をいいことに","explanationKo":"문맥상 〜을 기회로 악용해를 나타내는 「〜をいいことに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-02','reading',1,'資料の版を残す理由','{"passage":"文書やデータを更新して最新版を配布することには、誤りを直し現状に合う情報を提供できることという意義がある。しかし、最新版だけを残すと過去の判断がどの情報に基づいたか分からないことには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、版番号と変更理由と適用開始日を記録することが重要なのである。","questions":[{"prompt":"「資料の版を残す理由」について筆者が最も重視していることは何か。","options":["版番号と変更理由と適用開始日を記録すること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"版番号と変更理由と適用開始日を記録すること","explanationKo":"본문에서는 版番号と変更理由と適用開始日を記録すること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["最新版だけを残すと過去の判断がどの情報に基づいたか分からないこと","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"最新版だけを残すと過去の判断がどの情報に基づいたか分からないこと","explanationKo":"주의할 점은 最新版だけを残すと過去の判断がどの情報に基づいたか分からないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["誤りを直し現状に合う情報を提供できること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"誤りを直し現状に合う情報を提供できること","explanationKo":"文書やデータを更新して最新版を配布すること에는 誤りを直し現状に合う情報を提供できること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',1,'文字・語彙','{"type":"kanji_reading","wordKey":"n1-4381","prompt":"「インテリ」の読み方として最も適切なものを選びなさい。","options":["いんてり","でいりぐち","あくせる","べすと"],"answer":"いんてり","explanationKo":"「インテリ」는 「いんてり」라고 읽는다. 뜻은 지식인; 인텔리이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
