INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',9,'文字・語彙','{"type":"context_fill","wordKey":"n1-4389","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n事故現場に（　）が到着した。","options":["パトカー","グラフ","ソロ","切り"],"answer":"パトカー","explanationKo":"문맥상 「パトカー」가 가장 자연스럽다. 순찰차; 경찰차라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',10,'文字・語彙','{"type":"context_fill","wordKey":"n1-4390","prompt":"次の文の（　）に入る語として最も適切なものを選びなさい。\n椅子の中の（　）が壊れた。","options":["難","コメント","レクリエーション","スプリング"],"answer":"スプリング","explanationKo":"문맥상 「スプリング」가 가장 자연스럽다. 스프링; 용수철라는 의미로 쓰였다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',11,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4391","prompt":"「川などが始まる場所。また、物事が生じる根本・起源。」という意味に最も近い語を選びなさい。","options":["盗み","地方","源","ドリル"],"answer":"源","explanationKo":"「源」의 핵심 의미는 근원; 원천; 발원지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',12,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4392","prompt":"「人・物の姿をかたどったもの。また、心に描かれる姿・イメージ。」という意味に最も近い語を選びなさい。","options":["当て","像","侍","日の丸"],"answer":"像","explanationKo":"「像」의 핵심 의미는 상; 형상; 이미지이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',13,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4393","prompt":"「表面や名目に対する、実際の内容・真実。『実は』の形では、事実を打ち明ける時にも用いる。」という意味に最も近い語を選びなさい。","options":["実","各種","見晴らし","アルミ"],"answer":"実","explanationKo":"「実」의 핵심 의미는 실제; 진실; 사실이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',14,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4394","prompt":"「印刷に用いる版。また、内容・時期などが異なる出版物の版やバージョン。」という意味に最も近い語を選びなさい。","options":["話し合い","ファン","スペース","版"],"answer":"版","explanationKo":"「版」의 핵심 의미는 판; 판본; 버전이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','vocab_question',15,'文字・語彙','{"type":"meaning_usage_synonym","wordKey":"n1-4395","prompt":"「金銭・土地・物品など、経済的な価値を持つ財産。」という意味に最も近い語を選びなさい。","options":["サイクル","版","財","コミュニケーション"],"answer":"財","explanationKo":"「財」의 핵심 의미는 재산; 재물; 자산이다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','grammar',1,'〜をいいことに','{"pattern":"〜をいいことに","meaningKo":"〜을 기회로 악용해","explanation":"〜をいいことに는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"監視がないのをいいことに、規則を破る人がいた。","ko":"문맥에서 〜을 기회로 악용해의 의미로 쓰였다."},{"ja":"相手が反論しないのをいいことに、責任を押しつけた。","ko":"이 문장도 〜을 기회로 악용해의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','grammar',2,'〜を禁じ得ない','{"pattern":"〜を禁じ得ない","meaningKo":"〜을 금할 수 없다","explanation":"〜を禁じ得ない는 문장 앞뒤의 논리 관계와 접속 형태를 함께 확인해야 하는 N1 문법 표현이다.","examples":[{"ja":"度重なる不正に、怒りを禁じ得ない。","ko":"문맥에서 〜을 금할 수 없다의 의미로 쓰였다."},{"ja":"被災地の光景を前に、涙を禁じ得なかった。","ko":"이 문장도 〜을 금할 수 없다의 용법을 보여 준다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','grammar_question',1,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n監視がないの（　）、規則を破る人がいた。","options":["〜そびれる","〜ずとも","〜とみるや","〜をいいことに"],"answer":"〜をいいことに","explanationKo":"문맥상 〜을 기회로 악용해를 나타내는 「〜をいいことに」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','grammar_question',2,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n度重なる不正に、怒り（　）。","options":["〜すら","〜ないまでも","〜を禁じ得ない","〜きれない"],"answer":"〜を禁じ得ない","explanationKo":"문맥상 〜을 금할 수 없다를 나타내는 「〜を禁じ得ない」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','grammar_question',3,'文法','{"prompt":"次の文の（　）に入る表現として最も適切なものを選びなさい。\n改善した（　）、別の不具合が見つかった。","options":["〜にあらず","〜かと思えば","〜かねない","〜だに"],"answer":"〜かと思えば","explanationKo":"문맥상 〜인가 했더니를 나타내는 「〜かと思えば」가 알맞다."}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
INSERT INTO japanese_jlpt_daily_contents(plan_id,study_date,content_type,sequence_no,title,payload_json) SELECT id,'2027-03-03','reading',1,'語彙学習を終点にしない','{"passage":"多数の語と意味を体系的に覚えることには、文章を読む速度と表現の選択肢を増やせることという意義がある。しかし、一覧を暗記するだけでは文脈に合う読みや使い方を選べないことには注意が必要だ。名称や数字だけで判断せず、実際の用例と利用者への影響を確かめなければならない。したがって、例文で意味を判定し自分の言葉で言い換える練習を続けることが重要なのである。","questions":[{"prompt":"「語彙学習を終点にしない」について筆者が最も重視していることは何か。","options":["例文で意味を判定し自分の言葉で言い換える練習を続けること","名称だけで意味を固定すること","例外を検討から除くこと","利用後の影響を確認しないこと"],"answer":"例文で意味を判定し自分の言葉で言い換える練習を続けること","explanationKo":"본문에서는 例文で意味を判定し自分の言葉で言い換える練習を続けること 것이 가장 중요하다고 본다."},{"prompt":"本文で注意すべき点として述べられているものは何か。","options":["一覧を暗記するだけでは文脈に合う読みや使い方を選べないこと","用例を増やすと意味が失われること","複数の条件を示すと判断できなくなること","利用者の影響を調べると更新できないこと"],"answer":"一覧を暗記するだけでは文脈に合う読みや使い方を選べないこと","explanationKo":"주의할 점은 一覧を暗記するだけでは文脈に合う読みや使い方を選べないこと 가능성이다."},{"prompt":"本文の内容と一致するものはどれか。","options":["文章を読む速度と表現の選択肢を増やせること","名称だけを根拠に結論を出すべきだ","実際の利用状況は確認しなくてよい","例外的な用法は記録から除くべきだ"],"answer":"文章を読む速度と表現の選択肢を増やせること","explanationKo":"多数の語と意味を体系的に覚えること에는 文章を読む速度と表現の選択肢を増やせること라는 장점이 있다."}]}' FROM japanese_jlpt_study_plans WHERE plan_code='N1_2027_JUL';
